0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #652c95; transition: background .15s; }\\n.rbg-card:hover { background:#f3eef8; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #652c95; }\\n.rbg-warning { border-left:8px solid #ffdd00; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#ffdd00; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"RBG Purple","color":"#652c95"},{"slug":"rbg-purple-dark","name":"RBG Purple Dark","color":"#4b1f6f"},{"slug":"focus-yellow","name":"Focus Yellow","color":"#ffdd00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer Grey","color":"#505a5f"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Light Purple","color":"#f3eef8"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-21 21:04:37','2026-11-21 21:04:37','',5,'https://rbg-coursework-demo.page.gd/?p=13',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (14,1,'2026-11-22 02:58:22','2026-11-22 02:58:22','<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"1.4rem\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:1.4rem\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Phone 020 8854 8888, or visit us at The Woolwich Centre, Wellington Street, SE18 6HQ. <a href=\"/contact-us/\">See all ways to contact us</a>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','','','trash','closed','closed','','__trashed','','','2026-11-22 02:58:22','2026-11-22 02:58:22','',0,'https://rbg-coursework-demo.page.gd/?page_id=14',0,'page','',0);
INSERT INTO `wp_posts` VALUES (15,1,'2026-11-21 21:06:00','2026-11-21 21:06:00','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class="wp-block-quote">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class="wp-block-quote">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href="https://rbg-coursework-demo.page.gd/wp-admin/">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','inherit','closed','closed','','2-revision-v1','','','2026-11-21 21:06:00','2026-11-21 21:06:00','',2,'https://rbg-coursework-demo.page.gd/?p=15',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (16,1,'2026-11-21 21:06:00','2026-11-21 21:06:00','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','inherit','closed','closed','','1-revision-v1','','','2026-11-21 21:06:00','2026-11-21 21:06:00','',1,'https://rbg-coursework-demo.page.gd/?p=16',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (17,1,'2026-11-21 21:06:00','2026-11-21 21:06:00','<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-hero\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff\"}},\"heading\":{\"color\":{\"text\":\"#ffffff\"}}}},\"backgroundColor\":\"rbg-purple\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n<div class=\"wp-block-group alignfull rbg-hero has-white-color has-rbg-purple-background-color has-text-color has-background has-link-color\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:heading {\"level\":1,\"textColor\":\"white\"} -->\n<h1 class=\"wp-block-heading has-white-color has-text-color\">Find a service or report a problem</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Information and services for people who live, work in and visit Royal Greenwich.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:search {\"label\":\"Search the website\",\"placeholder\":\"For example, bin collection day\",\"width\":100,\"widthUnit\":\"%\",\"buttonText\":\"Search\",\"className\":\"rbg-hero-search\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"rbg-home\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n<div class=\"wp-block-group rbg-home\"><!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Popular tasks</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Tell us about rubbish dumped on a street or public land. Add a photo.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Tell us if we did not empty your bin on your collection day.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Enter your postcode to see which day we collect your bins.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Our services</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/recycling-and-rubbish/\">Recycling and rubbish</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bin days, missed bins, recycling and household waste.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/parking-transport-and-streets/\">Parking, transport and streets</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Report street problems, parking permits and fines.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Council Tax</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pay, check your bill or apply for a discount. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Housing</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Repairs, rent and finding a home. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Adult care and health</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Support to live independently. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Schools and education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>School places, term dates and free school meals. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Latest news</h2>\n<!-- /wp:heading -->\n\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false,\"excludeCurrent\":null}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"style\":{\"typography\":{\"fontSize\":\"1.2rem\"}}} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}},\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/news/\">See all news</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"1.4rem\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:1.4rem\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Phone 020 8854 8888, or visit us at The Woolwich Centre, Wellington Street, SE18 6HQ. <a href=\"/contact-us/\">See all ways to contact us</a>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Home','','publish','closed','closed','','home','','','2026-11-22 02:58:38','2026-11-22 02:58:38','',0,'https://rbg-coursework-demo.page.gd/home/',0,'page','',0);
INSERT INTO `wp_posts` VALUES (18,1,'2026-11-21 21:06:00','2026-11-21 21:06:00','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Find your bin collection day, report a missed bin, or check what goes in which bin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/\">Bins and collections</a><br>Find your bin day, report a missed bin and check what goes in each bin.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Recycling and reducing your waste</strong><br>Tips to reduce waste and recycle more. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Household waste</strong><br>Bulky waste collections and the reuse and recycling centre. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Business waste</strong><br>Arrange a trade waste collection for your business. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Recycling and rubbish','','publish','closed','closed','','recycling-and-rubbish','','','2026-11-22 02:54:14','2026-11-22 02:54:14','',0,'https://rbg-coursework-demo.page.gd/recycling-and-rubbish/',1,'page','',0);
INSERT INTO `wp_posts` VALUES (19,1,'2026-11-21 21:06:00','2026-11-21 21:06:00','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Check your collection day, tell us if we missed your bin, and find out what goes in each bin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a><br>Enter your postcode to see which day we collect your bins.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a><br>Tell us if we did not empty your bin on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Check what to put in your bins</strong><br>What goes in the black, blue and green top bins and the food caddy. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>If you put the wrong items in your bin</strong><br>What a red tag on your bin means and what to do next. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Order bins, bags or labels</strong><br>Request a new or replacement bin. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Bank holiday collection dates</strong><br>Revised collection days around bank holidays. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Bins and collections','','publish','closed','closed','','bins-and-collections','','','2026-11-22 02:54:28','2026-11-22 02:54:28','',18,'https://rbg-coursework-demo.page.gd/recycling-and-rubbish/bins-and-collections/',1,'page','',0);
INSERT INTO `wp_posts` VALUES (20,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Enter your postcode to check which day we collect your rubbish and recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"rbg-binday\">\n<label for=\"rbg-postcode\" style=\"display:block;font-weight:700;font-size:1.15rem\">Enter your postcode</label>\n<p id=\"rbg-postcode-hint\" style=\"margin:.25rem 0 .5rem;color:#505a5f\">For example, SE10 9GB</p>\n<div style=\"display:flex;flex-wrap:wrap;gap:.5rem;align-items:stretch\">\n<input id=\"rbg-postcode\" type=\"text\" autocomplete=\"postal-code\" spellcheck=\"false\" aria-describedby=\"rbg-postcode-hint\" style=\"font-size:1.1rem;padding:.55rem .7rem;border:2px solid #0b0c0c;min-height:44px;max-width:12rem;width:100%\">\n<button type=\"button\" id=\"rbg-find\" class=\"wp-element-button\" style=\"min-height:44px\">Find my bin day</button>\n</div>\n<div id=\"rbg-result\" role=\"status\" aria-live=\"polite\" style=\"margin-top:1rem\"></div>\n</div>\n<script>\n(function(){\n  var days = {SE2:\'Monday\', SE3:\'Tuesday\', SE7:\'Wednesday\', SE9:\'Thursday\', SE10:\'Friday\', SE12:\'Thursday\', SE18:\'Monday\', SE28:\'Tuesday\'};\n  var input = document.getElementById(\'rbg-postcode\'), out = document.getElementById(\'rbg-result\');\n  if (!input) return;\n  function find(){\n    var pc = (input.value || \'\').toUpperCase().replace(/\\s+/g,\'\');\n    var m = pc.match(/^(SE\\d{1,2})(\\d[A-Z]{2})?$/);\n    if (!pc) { out.innerHTML = \'<p style=\"color:#d4351c;font-weight:700\">Enter a postcode</p>\'; input.focus(); return; }\n    var district = m ? m[1] : null;\n    if (district && days[district]) {\n      out.innerHTML = \'<div style=\"background:#faf6e9;border-left:8px solid #d4af37;padding:1rem 1.25rem\"><p style=\"margin:0;font-size:1.25rem\"><strong>\' + district + \': your bins are collected on \' + days[district] + \'</strong></p><p style=\"margin:.5rem 0 0\">Put your bins out by 6am. We collect between 6am and 8pm. <a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a></p></div>\';\n    } else {\n      out.innerHTML = \'<p><strong>We could not find that postcode in Royal Greenwich.</strong> Check it and try again, or <a href=\"/contact-us/\">contact us</a>.</p>\';\n    }\n  }\n  document.getElementById(\'rbg-find\').addEventListener(\'click\', find);\n  input.addEventListener(\'keydown\', function(e){ if (e.key === \'Enter\') { e.preventDefault(); find(); } });\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Demo data:</strong> this lookup uses sample collection days by postcode area. The live service would check your exact address against the council’s collection rounds.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Collection days by area (sample)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"hasFixedLayout\":false} -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Postcode area</th><th>Areas covered</th><th>Collection day</th></tr></thead><tbody><tr><td>SE2</td><td>Abbey Wood</td><td>Monday</td></tr><tr><td>SE3</td><td>Blackheath, Kidbrooke</td><td>Tuesday</td></tr><tr><td>SE7</td><td>Charlton</td><td>Wednesday</td></tr><tr><td>SE9</td><td>Eltham, Mottingham</td><td>Thursday</td></tr><tr><td>SE10</td><td>Greenwich, Greenwich Peninsula</td><td>Friday</td></tr><tr><td>SE12</td><td>Lee, Grove Park (Greenwich part)</td><td>Thursday</td></tr><tr><td>SE18</td><td>Woolwich, Plumstead, Shooters Hill</td><td>Monday</td></tr><tr><td>SE28</td><td>Thamesmead</td><td>Tuesday</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Sample bin collection days for this demo</figcaption></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before your collection</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Put your bins out by 6am on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We collect between 6am and 8pm, so the time can change from week to week.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you live in a flat or on an estate, ask your caretaker or managing agent for your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Collections that fall on a bank holiday move to a new date.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">If we did not empty your bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a> by midnight on the day after your collection day.</p>\n<!-- /wp:paragraph -->','Find your bin collection day','','publish','closed','closed','','find-your-bin-collection-day','','','2026-11-22 04:00:00','2026-11-22 04:00:00','',19,'https://rbg-coursework-demo.page.gd/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/',1,'page','',0);
INSERT INTO `wp_posts` VALUES (21,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Use this form if we did not empty your bin on your collection day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before you report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We collect bins between 6am and 8pm, so wait until after 8pm on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your bin needs to be out by 6am. If it was not, we cannot come back for it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If we missed your whole street, you do not need to tell us. We will aim to collect by the end of the week, including the weekend.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Report a missed bin by midnight on the day after your collection day.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">If we put a red tag on your bin</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Blue and green top recycling bins are not emptied if they contain the wrong items. We put a red tag on the bin and send you a letter explaining why. You do not need to report a tagged bin as missed.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Report a missed bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[forminator_form id=\"80\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<script>\n(function(){\n  var ref = \'MB-\' + String(Date.now()).slice(-6);\n  function setRef(){ document.querySelectorAll(\'input[name=\"text-3\"]\').forEach(function(i){ if (!i.value) i.value = ref; }); }\n  document.addEventListener(\'DOMContentLoaded\', setRef);\n  document.addEventListener(\'submit\', setRef, true);\n  document.addEventListener(\'click\', function(e){ if (e.target.closest && e.target.closest(\'.forminator-button-submit\')) setRef(); }, true);\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The waste team will check the collection round and arrange to collect your bin as soon as possible.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Leave your bin out until we have emptied it.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 4661. See all <a href=\"/contact-us/\">ways to contact us</a>.</p>\n<!-- /wp:paragraph -->','Report a missed bin','','publish','closed','closed','','report-missed-bin','','','2026-11-22 02:54:38','2026-11-22 02:54:38','',19,'https://rbg-coursework-demo.page.gd/recycling-and-rubbish/bins-and-collections/report-missed-bin/',2,'page','',0);
INSERT INTO `wp_posts` VALUES (22,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Report a problem on a street, apply for a parking permit or pay a parking fine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/\">Report issues on a street</a><br>Report fly-tipping, graffiti, potholes and other street problems.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Parking permits</strong><br>Apply for or renew a resident or visitor permit. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Parking fines (PCNs)</strong><br>Pay or challenge a penalty charge notice. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Roads and pavements</strong><br>Roadworks, road safety and highway licences. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Parking, transport and streets','','publish','closed','closed','','parking-transport-and-streets','','','2026-11-22 02:54:48','2026-11-22 02:54:48','',0,'https://rbg-coursework-demo.page.gd/parking-transport-and-streets/',2,'page','',0);
INSERT INTO `wp_posts` VALUES (23,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Tell us about a problem on a road, pavement or public space, and we will send it to the right team.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a><br>Rubbish dumped on a street, pavement or council land.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report graffiti</strong><br>Graffiti on public property. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report a pothole or damaged pavement</strong><br>Damage to a road or footway we look after. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report an abandoned vehicle</strong><br>A vehicle that looks dumped or untaxed. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report a street light fault</strong><br>A light that is out, flickering or damaged. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report an abandoned shopping trolley</strong><br>Trolleys are collected by Trolleywise for the retailers. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Report issues on a street','','publish','closed','closed','','report-issues-street','','','2026-11-22 02:54:53','2026-11-22 02:54:53','',22,'https://rbg-coursework-demo.page.gd/parking-transport-and-streets/report-issues-street/',1,'page','',0);
INSERT INTO `wp_posts` VALUES (24,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Fly-tipping is rubbish dumped where it should not be, from a single bin bag to a mattress or a pile of builders’ waste. We investigate and clear fly-tips on land we are responsible for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">When we cannot help</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Private land:</strong> the owner or occupier must clear it, including shared alleyways and access roads.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Red routes:</strong> these roads are managed by Transport for London. <a href=\"https://tfl.gov.uk/\">Report it to TfL</a>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Shopping trolleys:</strong> these belong to the shops. Report abandoned trolleys to Trolleywise.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will need</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>exactly where it is: street, nearest house number or landmark, and postcode</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>when you saw it</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>who left it, if you know</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>a photo, if you can take one safely</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Stay safe:</strong> do not touch or move the rubbish, especially if it could be hazardous, such as asbestos, chemicals or needles. Never approach anyone you see fly-tipping.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Tell us about a fly-tip</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[forminator_form id=\"66\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<script>\n(function(){\n  var ref = \'FT-\' + String(Date.now()).slice(-6);\n  function setRef(){ document.querySelectorAll(\'input[name=\"text-3\"]\').forEach(function(i){ if (!i.value) i.value = ref; }); }\n  document.addEventListener(\'DOMContentLoaded\', setRef);\n  document.addEventListener(\'submit\', setRef, true);\n  document.addEventListener(\'click\', function(e){ if (e.target.closest && e.target.closest(\'.forminator-button-submit\')) setRef(); }, true);\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report goes to the Street Services team. Reports of hazardous waste go to the Environmental Crime team.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 5025. You can leave a message at any time, and we reply Monday to Friday, 9am to 5pm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Email <a href=\"mailto:envirocrime@royalgreenwich.gov.uk\">envirocrime@royalgreenwich.gov.uk</a>.</p>\n<!-- /wp:paragraph -->','Report a fly-tip','','publish','closed','closed','','report-fly-tip','','','2026-11-22 02:53:35','2026-11-22 02:53:35','',23,'https://rbg-coursework-demo.page.gd/parking-transport-and-streets/report-issues-street/report-fly-tip/',1,'page','',0);
INSERT INTO `wp_posts` VALUES (25,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:html -->\n<div class=\"rbg-panel\" style=\"background:#0b0c0c;color:#fff;padding:1.75rem 1.5rem;border-radius:4px;border-top:6px solid #d4af37\">\n<p style=\"margin:0;font-size:1.6rem;font-weight:700;font-family:var(--wp--preset--font-family--kantumruy-pro);color:#d4af37\">Thank you, we have received your report</p>\n<p id=\"rbg-ref-line\" style=\"margin:.75rem 0 0;font-size:1.2rem\">We have emailed your reference number to you.</p>\n</div>\n<script>\ndocument.addEventListener(\'DOMContentLoaded\', function(){\n  var q = new URLSearchParams(location.search), ref = (q.get(\'ref\')||\'\').replace(/[^0-9A-Za-z-]/g,\'\'), type = q.get(\'type\');\n  var prefix = type === \'missed-bin\' ? \'MB-\' : (type === \'fly-tip\' ? \'FT-\' : \'RBG-\');\n  var el = document.getElementById(\'rbg-ref-line\');\n  if (ref && ref !== \'0\' && el) { var shown = /^(FT|MB)-/.test(ref) ? ref : prefix + ref; el.innerHTML = \'Your reference number is<br><strong style=\"font-size:2rem;letter-spacing:.05em;color:#d4af37\">\' + shown + \'</strong>\'; }\n  var t = document.getElementById(\'rbg-timescale\');\n  if (t && type === \'fly-tip\') t.textContent = \'We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.\';\n  if (t && type === \'missed-bin\') t.textContent = \'We will arrange to collect your bin as soon as possible. Please leave it out until we do.\';\n});\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We have sent a confirmation email with your reference number and a copy of your answers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report has gone straight to the team that deals with it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span id=\"rbg-timescale\">We will deal with your report as quickly as we can.</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you need to contact us about this report, quote your reference number.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Is there anything else?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/parking-transport-and-streets/report-issues-street/\">Report another street problem</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/\">Back to the homepage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Report received','','publish','closed','closed','','report-received','','','2026-11-22 04:00:00','2026-11-22 04:00:00','',0,'https://rbg-coursework-demo.page.gd/report-received/',10,'page','',0);
INSERT INTO `wp_posts` VALUES (26,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','','News','','publish','closed','closed','','news','','','2026-11-22 02:55:15','2026-11-22 02:55:15','',0,'https://rbg-coursework-demo.page.gd/news/',11,'page','',0);
INSERT INTO `wp_posts` VALUES (27,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Most of our services are available online at any time. You can also phone, email, write to us or visit a service centre.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Emergencies:</strong> if someone is in immediate danger, call 999.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Phone and email</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Phone: 020 8854 8888</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Email: <a href=\"mailto:contact.centre@royalgreenwich.gov.uk\">contact.centre@royalgreenwich.gov.uk</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Visit us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>The Woolwich Centre</strong><br>Wellington Street<br>Woolwich<br>SE18 6HQ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You can also visit the Eltham Centre.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Write to us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Customer Services, The Woolwich Centre, Wellington Street, Woolwich, SE18 6HQ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Help to contact us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>British Sign Language:</strong> contact us through SignVideo, a free video interpreting service.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Other languages:</strong> the Royal Greenwich Interpreting Service can help you speak to us in your language.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Translating this website:</strong> most browsers can translate pages into other languages.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Contact a service team</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/\">Recycling and waste</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/\">Street cleaning and fly-tipping</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Council Tax, Housing, Parking and other teams <em>(not included in this demo)</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->','Contact us','','publish','closed','closed','','contact-us','','','2026-11-22 02:55:20','2026-11-22 02:55:20','',0,'https://rbg-coursework-demo.page.gd/contact-us/',12,'page','',0);
INSERT INTO `wp_posts` VALUES (28,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph -->\n<p>This accessibility statement applies to this demonstration website for the Royal Borough of Greenwich.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p>This is a student coursework prototype, not the official council website. The statement shows what a council site must publish under the accessibility regulations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Using this website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We want as many people as possible to be able to use this website. You should be able to:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>change colours, contrast levels and fonts using your browser or device settings</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>zoom in up to 400% without the text spilling off the screen</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>navigate the whole website using just a keyboard, with a clearly visible focus indicator</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>navigate most of the website using speech recognition software</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>listen to the website using a screen reader</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We have written the text to be as simple as possible to understand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How accessible this website is</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We aim to meet the Web Content Accessibility Guidelines (WCAG) version 2.2 at AA standard. We know some parts are not fully accessible yet:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>some photos uploaded by residents with reports may not have a text description</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>the sample bin day lookup works by postcode area only</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Reporting accessibility problems</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you find a problem that is not listed on this page, or you need information in a different format, <a href=\"/contact-us/\">contact us</a>. We will reply within 5 working days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Enforcement procedure</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The Equality and Human Rights Commission (EHRC) is responsible for enforcing the Public Sector Bodies (Websites and Mobile Applications) (No. 2) Accessibility Regulations 2018. If you are not happy with how we respond to your complaint, contact the Equality Advisory and Support Service (EASS).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How we tested this website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This prototype was tested with the WAVE accessibility checker, Lighthouse, keyboard-only navigation and at mobile screen widths.</p>\n<!-- /wp:paragraph -->','Accessibility statement','','publish','closed','closed','','accessibility','','','2026-11-22 02:55:25','2026-11-22 02:55:25','',0,'https://rbg-coursework-demo.page.gd/accessibility/',13,'page','',0);
INSERT INTO `wp_posts` VALUES (29,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Our website address is: https://rbg-coursework-demo.page.gd.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymised string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service Privacy Policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment on our site you may opt in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognise and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class="privacy-policy-tutorial">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy notice','','inherit','closed','closed','','3-revision-v1','','','2026-11-21 21:06:01','2026-11-21 21:06:01','',3,'https://rbg-coursework-demo.page.gd/?p=29',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (30,1,'2026-11-21 21:06:01','2026-11-21 21:06:01','<!-- wp:paragraph -->\n<p>Cookies are small files saved on your phone, tablet or computer when you visit a website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies on this demo site</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This demonstration site does not use analytics or advertising cookies. It only sets essential cookies:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>wordpress_logged_in and wordpress_sec:</strong> keep staff signed in to manage reports and content</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>wordpress_test_cookie:</strong> checks that your browser accepts cookies when staff sign in</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>If the council added analytics, such as Google Analytics, we would ask for your permission first.</p>\n<!-- /wp:paragraph -->','Cookies','','publish','closed','closed','','cookies','','','2026-11-22 02:55:36','2026-11-22 02:55:36','',0,'https://rbg-coursework-demo.page.gd/cookies/',15,'page','',0);
INSERT INTO `wp_posts` VALUES (31,1,'2026-11-21 21:06:26','2026-11-21 21:06:26','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Find your bin collection day, report a missed bin, or check what goes in which bin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/\">Bins and collections</a><br>Find your bin day, report a missed bin and check what goes in each bin.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Recycling and reducing your waste</strong><br>Tips to reduce waste and recycle more. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Household waste</strong><br>Bulky waste collections and the reuse and recycling centre. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Business waste</strong><br>Arrange a trade waste collection for your business. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Recycling and rubbish','','inherit','closed','closed','','18-revision-v1','','','2026-11-21 21:06:26','2026-11-21 21:06:26','',18,'https://rbg-coursework-demo.page.gd/?p=31',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (32,1,'2026-11-21 21:06:27','2026-11-21 21:06:27','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Check your collection day, tell us if we missed your bin, and find out what goes in each bin.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a><br>Enter your postcode to see which day we collect your bins.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a><br>Tell us if we did not empty your bin on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Check what to put in your bins</strong><br>What goes in the black, blue and green top bins and the food caddy. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>If you put the wrong items in your bin</strong><br>What a red tag on your bin means and what to do next. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Order bins, bags or labels</strong><br>Request a new or replacement bin. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Bank holiday collection dates</strong><br>Revised collection days around bank holidays. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Bins and collections','','inherit','closed','closed','','19-revision-v1','','','2026-11-21 21:06:27','2026-11-21 21:06:27','',19,'https://rbg-coursework-demo.page.gd/?p=32',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (33,1,'2026-11-21 21:06:27','2026-11-21 21:06:27','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Report a problem on a street, apply for a parking permit or pay a parking fine.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/\">Report issues on a street</a><br>Report fly-tipping, graffiti, potholes and other street problems.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Parking permits</strong><br>Apply for or renew a resident or visitor permit. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Parking fines (PCNs)</strong><br>Pay or challenge a penalty charge notice. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Roads and pavements</strong><br>Roadworks, road safety and highway licences. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Parking, transport and streets','','inherit','closed','closed','','22-revision-v1','','','2026-11-21 21:06:27','2026-11-21 21:06:27','',22,'https://rbg-coursework-demo.page.gd/?p=33',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (34,1,'2026-11-21 21:06:27','2026-11-21 21:06:27','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Tell us about a problem on a road, pavement or public space, and we will send it to the right team.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"className\":\"rbg-link-list\"} -->\n<ul class=\"wp-block-list rbg-link-list\"><!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a><br>Rubbish dumped on a street, pavement or council land.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report graffiti</strong><br>Graffiti on public property. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report a pothole or damaged pavement</strong><br>Damage to a road or footway we look after. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report an abandoned vehicle</strong><br>A vehicle that looks dumped or untaxed. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report a street light fault</strong><br>A light that is out, flickering or damaged. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span class=\"rbg-notbuilt\"><strong>Report an abandoned shopping trolley</strong><br>Trolleys are collected by Trolleywise for the retailers. <em>(not included in this demo)</em></span></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>About this demo:</strong> it shows two resident journeys, reporting a fly-tip and reporting a missed bin. Topics without a link are listed so the structure matches the real site.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Report issues on a street','','inherit','closed','closed','','23-revision-v1','','','2026-11-21 21:06:27','2026-11-21 21:06:27','',23,'https://rbg-coursework-demo.page.gd/?p=34',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (35,1,'2026-11-21 21:07:09','2026-11-21 21:07:09','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Enter your postcode to check which day we collect your rubbish and recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html /-->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Demo data:</strong> this lookup uses sample collection days by postcode area. The live service would check your exact address against the council’s collection rounds.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Collection days by area (sample)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"hasFixedLayout\":false} -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Postcode area</th><th>Areas covered</th><th>Collection day</th></tr></thead><tbody><tr><td>SE2</td><td>Abbey Wood</td><td>Monday</td></tr><tr><td>SE3</td><td>Blackheath, Kidbrooke</td><td>Tuesday</td></tr><tr><td>SE7</td><td>Charlton</td><td>Wednesday</td></tr><tr><td>SE9</td><td>Eltham, Mottingham</td><td>Thursday</td></tr><tr><td>SE10</td><td>Greenwich, Greenwich Peninsula</td><td>Friday</td></tr><tr><td>SE12</td><td>Lee, Grove Park (Greenwich part)</td><td>Thursday</td></tr><tr><td>SE18</td><td>Woolwich, Plumstead, Shooters Hill</td><td>Monday</td></tr><tr><td>SE28</td><td>Thamesmead</td><td>Tuesday</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Sample bin collection days for this demo</figcaption></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before your collection</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Put your bins out by 6am on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We collect between 6am and 8pm, so the time can change from week to week.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you live in a flat or on an estate, ask your caretaker or managing agent for your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Collections that fall on a bank holiday move to a new date.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">If we did not empty your bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a> by midnight on the day after your collection day.</p>\n<!-- /wp:paragraph -->','Find your bin collection day','','inherit','closed','closed','','20-revision-v1','','','2026-11-21 21:07:09','2026-11-21 21:07:09','',20,'https://rbg-coursework-demo.page.gd/?p=35',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (36,1,'2026-11-21 21:07:09','2026-11-21 21:07:09','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Use this form if we did not empty your bin on your collection day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before you report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We collect bins between 6am and 8pm, so wait until after 8pm on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your bin needs to be out by 6am. If it was not, we cannot come back for it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If we missed your whole street, you do not need to tell us. We will aim to collect by the end of the week, including the weekend.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Report a missed bin by midnight on the day after your collection day.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">If we put a red tag on your bin</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Blue and green top recycling bins are not emptied if they contain the wrong items. We put a red tag on the bin and send you a letter explaining why. You do not need to report a tagged bin as missed.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Report a missed bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>[FORM2_PLACEHOLDER]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>The waste team will check the collection round and arrange to collect your bin as soon as possible.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Leave your bin out until we have emptied it.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 4661. See all <a href=\"/contact-us/\">ways to contact us</a>.</p>\n<!-- /wp:paragraph -->','Report a missed bin','','inherit','closed','closed','','21-revision-v1','','','2026-11-21 21:07:09','2026-11-21 21:07:09','',21,'https://rbg-coursework-demo.page.gd/?p=36',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (37,1,'2026-11-21 21:07:09','2026-11-21 21:07:09','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Fly-tipping is rubbish dumped where it should not be, from a single bin bag to a mattress or a pile of builders’ waste. We investigate and clear fly-tips on land we are responsible for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">When we cannot help</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Private land:</strong> the owner or occupier must clear it, including shared alleyways and access roads.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Red routes:</strong> these roads are managed by Transport for London. <a href=\"https://tfl.gov.uk/\">Report it to TfL</a>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Shopping trolleys:</strong> these belong to the shops. Report abandoned trolleys to Trolleywise.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will need</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>exactly where it is: street, nearest house number or landmark, and postcode</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>when you saw it</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>who left it, if you know</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>a photo, if you can take one safely</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Stay safe:</strong> do not touch or move the rubbish, especially if it could be hazardous, such as asbestos, chemicals or needles. Never approach anyone you see fly-tipping.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Tell us about a fly-tip</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>[FORM1_PLACEHOLDER]</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report goes to the Street Services team. Reports of hazardous waste go to the Environmental Crime team.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 5025. You can leave a message at any time, and we reply Monday to Friday, 9am to 5pm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Email <a href=\"mailto:envirocrime@royalgreenwich.gov.uk\">envirocrime@royalgreenwich.gov.uk</a>.</p>\n<!-- /wp:paragraph -->','Report a fly-tip','','inherit','closed','closed','','24-revision-v1','','','2026-11-21 21:07:09','2026-11-21 21:07:09','',24,'https://rbg-coursework-demo.page.gd/?p=37',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (38,1,'2026-11-21 21:07:46','2026-11-21 21:07:46','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Enter your postcode to check which day we collect your rubbish and recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"rbg-binday\">\n<label for=\"rbg-postcode\" style=\"display:block;font-weight:700;font-size:1.15rem\">Enter your postcode</label>\n<p id=\"rbg-postcode-hint\" style=\"margin:.25rem 0 .5rem;color:#505a5f\">For example, SE10 9GB</p>\n<div style=\"display:flex;flex-wrap:wrap;gap:.5rem;align-items:stretch\">\n<input id=\"rbg-postcode\" type=\"text\" autocomplete=\"postal-code\" spellcheck=\"false\" aria-describedby=\"rbg-postcode-hint\" style=\"font-size:1.1rem;padding:.55rem .7rem;border:2px solid #0b0c0c;min-height:44px;max-width:12rem;width:100%\">\n<button type=\"button\" id=\"rbg-find\" class=\"wp-element-button\" style=\"min-height:44px\">Find my bin day</button>\n</div>\n<div id=\"rbg-result\" role=\"status\" aria-live=\"polite\" style=\"margin-top:1rem\"></div>\n</div>\n<script>\n(function(){\n  var days = {SE2:\'Monday\', SE3:\'Tuesday\', SE7:\'Wednesday\', SE9:\'Thursday\', SE10:\'Friday\', SE12:\'Thursday\', SE18:\'Monday\', SE28:\'Tuesday\'};\n  var input = document.getElementById(\'rbg-postcode\'), out = document.getElementById(\'rbg-result\');\n  if (!input) return;\n  function find(){\n    var pc = (input.value || \'\').toUpperCase().replace(/\\s+/g,\'\');\n    var m = pc.match(/^(SE\\d{1,2})(\\d[A-Z]{2})?$/);\n    if (!pc) { out.innerHTML = \'<p style=\"color:#d4351c;font-weight:700\">Enter a postcode</p>\'; input.focus(); return; }\n    var district = m ? m[1] : null;\n    if (district && days[district]) {\n      out.innerHTML = \'<div style=\"background:#f3eef8;border-left:8px solid #652c95;padding:1rem 1.25rem\"><p style=\"margin:0;font-size:1.25rem\"><strong>\' + district + \': your bins are collected on \' + days[district] + \'</strong></p><p style=\"margin:.5rem 0 0\">Put your bins out by 6am. We collect between 6am and 8pm. <a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a></p></div>\';\n    } else {\n      out.innerHTML = \'<p><strong>We could not find that postcode in Royal Greenwich.</strong> Check it and try again, or <a href=\"/contact-us/\">contact us</a>.</p>\';\n    }\n  }\n  document.getElementById(\'rbg-find\').addEventListener(\'click\', find);\n  input.addEventListener(\'keydown\', function(e){ if (e.key === \'Enter\') { e.preventDefault(); find(); } });\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Demo data:</strong> this lookup uses sample collection days by postcode area. The live service would check your exact address against the council’s collection rounds.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Collection days by area (sample)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"hasFixedLayout\":false} -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Postcode area</th><th>Areas covered</th><th>Collection day</th></tr></thead><tbody><tr><td>SE2</td><td>Abbey Wood</td><td>Monday</td></tr><tr><td>SE3</td><td>Blackheath, Kidbrooke</td><td>Tuesday</td></tr><tr><td>SE7</td><td>Charlton</td><td>Wednesday</td></tr><tr><td>SE9</td><td>Eltham, Mottingham</td><td>Thursday</td></tr><tr><td>SE10</td><td>Greenwich, Greenwich Peninsula</td><td>Friday</td></tr><tr><td>SE12</td><td>Lee, Grove Park (Greenwich part)</td><td>Thursday</td></tr><tr><td>SE18</td><td>Woolwich, Plumstead, Shooters Hill</td><td>Monday</td></tr><tr><td>SE28</td><td>Thamesmead</td><td>Tuesday</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Sample bin collection days for this demo</figcaption></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before your collection</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Put your bins out by 6am on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We collect between 6am and 8pm, so the time can change from week to week.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you live in a flat or on an estate, ask your caretaker or managing agent for your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Collections that fall on a bank holiday move to a new date.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">If we did not empty your bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a> by midnight on the day after your collection day.</p>\n<!-- /wp:paragraph -->','Find your bin collection day','','inherit','closed','closed','','20-revision-v1','','','2026-11-21 21:07:46','2026-11-21 21:07:46','',20,'https://rbg-coursework-demo.page.gd/?p=38',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (39,1,'2026-11-21 21:08:14','2026-11-21 21:08:14','<!-- wp:html -->\n<div class=\"rbg-panel\" style=\"background:#652c95;color:#fff;padding:1.75rem 1.5rem;border-radius:4px\">\n<p style=\"margin:0;font-size:1.6rem;font-weight:700;font-family:var(--wp--preset--font-family--kantumruy-pro)\">Thank you, we have received your report</p>\n<p id=\"rbg-ref-line\" style=\"margin:.75rem 0 0;font-size:1.2rem\">We have emailed your reference number to you.</p>\n</div>\n<script>\n(function(){\n  var q = new URLSearchParams(location.search), ref = (q.get(\'ref\')||\'\').replace(/[^0-9A-Za-z-]/g,\'\'), type = q.get(\'type\');\n  var prefix = type === \'missed-bin\' ? \'MB-\' : (type === \'fly-tip\' ? \'FT-\' : \'RBG-\');\n  var el = document.getElementById(\'rbg-ref-line\');\n  if (ref && el) { el.innerHTML = \'Your reference number is<br><strong style=\"font-size:2rem;letter-spacing:.05em\">\' + prefix + ref + \'</strong>\'; }\n  var t = document.getElementById(\'rbg-timescale\');\n  if (t && type === \'fly-tip\') t.textContent = \'We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.\';\n  if (t && type === \'missed-bin\') t.textContent = \'We will arrange to collect your bin as soon as possible. Please leave it out until we do.\';\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We have sent a confirmation email with your reference number and a copy of your answers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report has gone straight to the team that deals with it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span id=\"rbg-timescale\">We will deal with your report as quickly as we can.</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you need to contact us about this report, quote your reference number.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Is there anything else?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/parking-transport-and-streets/report-issues-street/\">Report another street problem</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/\">Back to the homepage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Report received','','inherit','closed','closed','','25-revision-v1','','','2026-11-21 21:08:14','2026-11-21 21:08:14','',25,'https://rbg-coursework-demo.page.gd/?p=39',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (40,1,'2026-11-21 21:08:14','2026-11-21 21:08:14','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Most of our services are available online at any time. You can also phone, email, write to us or visit a service centre.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Emergencies:</strong> if someone is in immediate danger, call 999.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Phone and email</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Phone: 020 8854 8888</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Email: <a href=\"mailto:contact.centre@royalgreenwich.gov.uk\">contact.centre@royalgreenwich.gov.uk</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Visit us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>The Woolwich Centre</strong><br>Wellington Street<br>Woolwich<br>SE18 6HQ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You can also visit the Eltham Centre.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Write to us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Customer Services, The Woolwich Centre, Wellington Street, Woolwich, SE18 6HQ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Help to contact us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>British Sign Language:</strong> contact us through SignVideo, a free video interpreting service.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Other languages:</strong> the Royal Greenwich Interpreting Service can help you speak to us in your language.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Translating this website:</strong> most browsers can translate pages into other languages.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Contact a service team</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/\">Recycling and waste</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/\">Street cleaning and fly-tipping</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Council Tax, Housing, Parking and other teams <em>(not included in this demo)</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->','Contact us','','inherit','closed','closed','','27-revision-v1','','','2026-11-21 21:08:14','2026-11-21 21:08:14','',27,'https://rbg-coursework-demo.page.gd/?p=40',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (41,1,'2026-11-21 21:08:15','2026-11-21 21:08:15','<!-- wp:paragraph -->\n<p>This accessibility statement applies to this demonstration website for the Royal Borough of Greenwich.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p>This is a student coursework prototype, not the official council website. The statement shows what a council site must publish under the accessibility regulations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Using this website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We want as many people as possible to be able to use this website. You should be able to:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>change colours, contrast levels and fonts using your browser or device settings</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>zoom in up to 400% without the text spilling off the screen</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>navigate the whole website using just a keyboard, with a clearly visible focus indicator</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>navigate most of the website using speech recognition software</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>listen to the website using a screen reader</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>We have written the text to be as simple as possible to understand.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How accessible this website is</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We aim to meet the Web Content Accessibility Guidelines (WCAG) version 2.2 at AA standard. We know some parts are not fully accessible yet:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>some photos uploaded by residents with reports may not have a text description</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>the sample bin day lookup works by postcode area only</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Reporting accessibility problems</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you find a problem that is not listed on this page, or you need information in a different format, <a href=\"/contact-us/\">contact us</a>. We will reply within 5 working days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Enforcement procedure</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The Equality and Human Rights Commission (EHRC) is responsible for enforcing the Public Sector Bodies (Websites and Mobile Applications) (No. 2) Accessibility Regulations 2018. If you are not happy with how we respond to your complaint, contact the Equality Advisory and Support Service (EASS).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How we tested this website</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This prototype was tested with the WAVE accessibility checker, Lighthouse, keyboard-only navigation and at mobile screen widths.</p>\n<!-- /wp:paragraph -->','Accessibility statement','','inherit','closed','closed','','28-revision-v1','','','2026-11-21 21:08:15','2026-11-21 21:08:15','',28,'https://rbg-coursework-demo.page.gd/?p=41',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (42,1,'2026-11-21 21:08:15','2026-11-21 21:08:15','<!-- wp:paragraph -->\n<p>This notice explains how we use the personal information you give us when you report a problem on this website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p>This is a student coursework prototype. Reports made on this demo site are stored only on the demo site and are not sent to the council.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What we collect</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>your name and email address, so we can send you a reference number and contact you about your report</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>the details of your report, such as the location and what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>any photo you choose to upload</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Why we use it</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We use your information to deal with your report. Our lawful basis under the UK General Data Protection Regulation (UK GDPR) is that this is a task we carry out in the public interest, as part of our duties to keep streets clean and collect waste.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who can see it</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Only staff in the team that deals with your report, and their managers, can see your details. Reports are never published on the website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we keep it</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We keep report details for 2 years after the report is closed, then delete them.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Your rights</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>You can ask to see the information we hold about you, ask us to correct it or, in some cases, ask us to delete it. You can also complain to the Information Commissioner’s Office (ICO).</p>\n<!-- /wp:paragraph -->','Privacy notice','','inherit','closed','closed','','3-revision-v1','','','2026-11-21 21:08:15','2026-11-21 21:08:15','',3,'https://rbg-coursework-demo.page.gd/?p=42',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (43,1,'2026-11-21 21:08:16','2026-11-21 21:08:16','<!-- wp:paragraph -->\n<p>Cookies are small files saved on your phone, tablet or computer when you visit a website.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies on this demo site</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This demonstration site does not use analytics or advertising cookies. It only sets essential cookies:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>wordpress_logged_in and wordpress_sec:</strong> keep staff signed in to manage reports and content</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>wordpress_test_cookie:</strong> checks that your browser accepts cookies when staff sign in</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>If the council added analytics, such as Google Analytics, we would ask for your permission first.</p>\n<!-- /wp:paragraph -->','Cookies','','inherit','closed','closed','','30-revision-v1','','','2026-11-21 21:08:16','2026-11-21 21:08:16','',30,'https://rbg-coursework-demo.page.gd/?p=43',0,'revision','',0);
