INSERT INTO `wp_posts` VALUES (46,1,'2026-11-21 21:08:43','2026-11-21 21:08:43','','Illustration of a mattress and rubbish bags dumped on a pavement','','inherit','closed','closed','','illustration-of-a-mattress-and-rubbish-bags-dumped-on-a-pavement','','','2026-11-21 21:08:43','2026-11-21 21:08:43','',0,'https://rbg-coursework-demo.page.gd/wp-content/uploads/2026/11/news-flytip.png',0,'attachment','image/png',0);
INSERT INTO `wp_posts` VALUES (47,1,'2026-11-18 10:00:00','2026-11-18 10:00:00','<!-- wp:paragraph -->\n<p>Residents can now report fly-tipping on our website in a couple of minutes, without creating an account.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The new form asks what has been dumped and where, and lets you add a photo. You get a reference number straight away by email, and your report goes directly to the right team. Reports of hazardous waste, such as asbestos or chemicals, are sent to the Environmental Crime team.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Go to <a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a>. We aim to clear fly-tips within 48 hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Report fly-tipping in under two minutes with our new online form','Residents can now report dumped rubbish, add a photo and get a reference number straight away.','publish','closed','closed','','report-fly-tipping-in-under-two-minutes-with-our-new-online-form','','','2026-11-22 03:57:31','2026-11-22 03:57:31','',0,'https://rbg-coursework-demo.page.gd/report-fly-tipping-in-under-two-minutes-with-our-new-online-form/',0,'post','',0);
INSERT INTO `wp_posts` VALUES (48,1,'2026-11-14 09:30:00','2026-11-14 09:30:00','<!-- wp:paragraph -->\n<p>Bin collections will move over Christmas and New Year because of the bank holidays.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Use <a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a> to check when we will collect your bins. Put your bins out by 6am on your collection day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Extra recycling</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Flatten cardboard boxes and put them next to your blue top bin. We will take them away with your recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Christmas and New Year bin collection changes','Bin collections will move over the festive period. Check your day before you put your bins out.','publish','closed','closed','','christmas-and-new-year-bin-collection-changes','','','2026-11-22 03:57:31','2026-11-22 03:57:31','',0,'https://rbg-coursework-demo.page.gd/christmas-and-new-year-bin-collection-changes/',0,'post','',0);
INSERT INTO `wp_posts` VALUES (49,1,'2026-11-07 14:00:00','2026-11-07 14:00:00','<!-- wp:paragraph -->\n<p>Garden waste collections are changing to every two weeks over the winter, when less garden waste is produced.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Your black top and blue top bin collections are not changing. If we miss your bin, you can <a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">report a missed bin</a> online.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Green top garden waste bins back to fortnightly collections','Garden waste collections return to every two weeks over the winter months.','publish','closed','closed','','green-top-garden-waste-bins-back-to-fortnightly-collections','','','2026-11-22 03:57:32','2026-11-22 03:57:32','',0,'https://rbg-coursework-demo.page.gd/green-top-garden-waste-bins-back-to-fortnightly-collections/',0,'post','',0);
