oup --></div>\n<!-- /wp:group -->\n\n','Header','','publish','closed','closed','','header','','','2026-11-22 10:34:07','2026-11-22 10:34:07','',0,'https://rbg-coursework-demo.page.gd/header/',0,'wp_template_part','',0);
INSERT INTO `wp_posts` VALUES (53,1,'2026-11-21 21:10:00','2026-11-21 21:10:00','<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-footer\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"},\"margin\":{\"top\":\"var:preset|spacing|60\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff\"}}}},\"backgroundColor\":\"footer-grey\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull rbg-footer has-white-color has-footer-grey-background-color has-text-color has-background has-link-color\" style=\"margin-top:var(--wp--preset--spacing--60);padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:columns {\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-white-color has-text-color has-large-font-size\">Contact us</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Phone: 020 8854 8888</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The Woolwich Centre<br>Wellington Street<br>Woolwich SE18 6HQ</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/contact-us/\">All ways to contact us</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-white-color has-text-color has-large-font-size\">Popular tasks</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"rbg-footer-list\"} -->\n<ul class=\"wp-block-list rbg-footer-list\"><!-- wp:list-item -->\n<li><a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textColor\":\"white\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-white-color has-text-color has-large-font-size\">About this site</h2>\n<!-- /wp:heading -->\n\n<!-- wp:navigation {\"ref\":51,\"textColor\":\"white\",\"overlayMenu\":\"never\",\"style\":{\"spacing\":{\"blockGap\":\"0.5rem\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:separator {\"align\":\"wide\",\"className\":\"is-style-wide\",\"style\":{\"color\":{\"background\":\"#ffffff\"}},\"backgroundColor\":\"white\"} -->\n<hr class=\"wp-block-separator alignwide has-text-color has-white-color has-alpha-channel-opacity has-white-background-color has-background is-style-wide\" style=\"background-color:#ffffff\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"className\":\"alignwide\",\"fontSize\":\"small\"} -->\n<p class=\"alignwide has-small-font-size\">Student coursework demonstration (COMP1643) built with WordPress. Not an official Royal Borough of Greenwich website. Some text is adapted from royalgreenwich.gov.uk for demonstration purposes.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Footer','','publish','closed','closed','','footer','','','2026-11-21 21:10:00','2026-11-21 21:10:00','',0,'https://rbg-coursework-demo.page.gd/footer/',0,'wp_template_part','',0);
