INSERT INTO `wp_posts` VALUES (55,1,'2026-11-21 21:10:18','2026-11-21 21:10:18','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:0;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:breadcrumbs {\"separator\":\"›\",\"className\":\"rbg-breadcrumbs\"} /-->\n\n<!-- wp:post-title {\"level\":1,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|20\"}}}} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"style\":{\"typography\":{\"fontSize\":\"1rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n\n<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} /-->\n\n<!-- wp:post-content {\"layout\":{\"type\":\"constrained\"}} /-->\n\n<!-- wp:paragraph -->\n<p><a href=\"/news/\">More news</a></p>\n<!-- /wp:paragraph --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','Single Posts','Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.','publish','closed','closed','','single','','','2026-11-21 21:13:11','2026-11-21 21:13:11','',0,'https://rbg-coursework-demo.page.gd/single/',0,'wp_template','',0);
