:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/parking-transport-and-streets/\">Parking, transport and streets</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Report street problems, parking permits and fines.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Council Tax</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pay, check your bill or apply for a discount. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Housing</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Repairs, rent and finding a home. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Adult care and health</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Support to live independently. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"padding-top:1.25rem;paddin