:paragraph -->\n<p>Tell us if we did not empty your bin on your collection day.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Enter your postcode to see which day we collect your bins.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Our services</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/recycling-and-rubbish/\">Recycling and rubbish</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bin days, missed bins, recycling and household waste.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/parking-transport-and-streets/\">Parking, transport and streets</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Report street problems, parking permits and fines.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Council Tax</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pay, check your bill or apply for a discount. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Housing</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Repairs, rent and finding a home. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Adult care and health</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Support to live independently. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Schools and education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>School places, term dates and free school meals. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Latest news</h2>\n<!-- /wp:heading -->\n\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"style\":{\"typography\":{\"fontSize\":\"1.2rem\"}}} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/news/\">See all news</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"1.4rem\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:1.4rem\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Phone 020 8854 8888, or visit us at The Woolwich Centre, Wellington Street, SE18 6HQ. <a href=\"/contact-us/\">See all ways to contact us</a>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Home','','inherit','closed','closed','','17-revision-v1','','','2026-11-21 21:11:48','2026-11-21 21:11:48','',17,'https://rbg-coursework-demo.page.gd/?p=59',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (60,1,'2026-11-21 21:11:55','2026-11-21 21:11:55','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#652c95"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#4b1f6f"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#652c95","text":"#ffffff"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#4b1f6f","text":"#ffffff"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #ffdd00 !important; }\\n.rbg-header a:focus-visible { background:#ffdd00; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #ffdd00; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #652c95; transition: background .15s; }\\n.rbg-card:hover { background:#f3eef8; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #652c95; }\\n.rbg-warning { border-left:8px solid #ffdd00; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#ffdd00; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #ffdd00; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"RBG Purple","color":"#652c95"},{"slug":"rbg-purple-dark","name":"RBG Purple Dark","color":"#4b1f6f"},{"slug":"focus-yellow","name":"Focus Yellow","color":"#ffdd00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer Grey","color":"#505a5f"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Light Purple","color":"#f3eef8"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-21 21:11:55','2026-11-21 21:11:55','',5,'https://rbg-coursework-demo.page.gd/?p=60',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (61,1,'2026-11-21 21:11:55','2026-11-21 21:11:55','<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-header\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff\"}}}},\"backgroundColor\":\"rbg-purple\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull rbg-header has-white-color has-rbg-purple-background-color has-text-color has-background has-link-color\" style=\"padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:site-title {\"level\":0,\"style\":{\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"1.65rem\",\"lineHeight\":\"1.1\"}},\"textColor\":\"white\",\"fontFamily\":\"kantumruy-pro\"} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:navigation {\"ref\":50,\"textColor\":\"white\",\"overlayBackgroundColor\":\"rbg-purple-dark\",\"overlayTextColor\":\"white\",\"style\":{\"typography\":{\"fontWeight\":\"600\",\"fontSize\":\"1.05rem\"},\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"right\",\"flexWrap\":\"wrap\"}} /-->\n\n<!-- wp:search {\"label\":\"Search\",\"showLabel\":false,\"placeholder\":\"Search\",\"width\":260,\"widthUnit\":\"px\",\"buttonText\":\"Search\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-demo-banner\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0.6rem\",\"bottom\":\"0.6rem\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull rbg-demo-banner has-light-grey-background-color has-background\" style=\"padding-top:0.6rem;padding-right:var(--wp--preset--spacing--40);padding-bottom:0.6rem;padding-left:var(--wp--preset--spacing--40)\"><!-- wp:paragraph {\"align\":\"left\",\"className\":\"alignwide\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-left alignwide has-small-font-size\"><strong><mark style=\"background-color:#652c95;color:#ffffff\" class=\"has-inline-color\"> DEMO </mark></strong> This is a student coursework prototype built in WordPress. It is not the official Royal Borough of Greenwich website.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Header','','inherit','closed','closed','','52-revision-v1','','','2026-11-21 21:11:55','2026-11-21 21:11:55','',52,'https://rbg-coursework-demo.page.gd/?p=61',0,'revision','',0);
