INSERT INTO `wp_posts` VALUES (64,1,'2026-11-21 21:13:11','2026-11-21 21:13:11','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:0;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:breadcrumbs {\"separator\":\"›\",\"className\":\"rbg-breadcrumbs\"} /-->\n\n<!-- wp:post-title {\"level\":1,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|20\"}}}} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"style\":{\"typography\":{\"fontSize\":\"1rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n\n<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} /-->\n\n<!-- wp:post-content {\"layout\":{\"type\":\"constrained\"}} /-->\n\n<!-- wp:paragraph -->\n<p><a href=\"/news/\">More news</a></p>\n<!-- /wp:paragraph --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','Single Posts','Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.','inherit','closed','closed','','55-revision-v1','','','2026-11-21 21:13:11','2026-11-21 21:13:11','',55,'https://rbg-coursework-demo.page.gd/?p=64',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (65,1,'2026-11-21 21:13:11','2026-11-21 21:13:11','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\" style=\"margin-top:0;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:breadcrumbs {\"separator\":\"›\",\"className\":\"rbg-breadcrumbs\"} /-->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">News</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The latest news from the council.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:query {\"queryId\":1,\"query\":{\"perPage\":10,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":true}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template -->\n<!-- wp:group -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:post-title {\"level\":2,\"isLink\":true,\"fontSize\":\"large\"} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n\n<!-- wp:post-excerpt {\"moreText\":\"\",\"showMoreOnNewLine\":false} /--></div>\n<!-- /wp:group -->\n<!-- /wp:post-template -->\n\n<!-- wp:query-pagination -->\n<!-- wp:query-pagination-previous /-->\n<!-- wp:query-pagination-numbers /-->\n<!-- wp:query-pagination-next /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:query --></main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','Blog Home','Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.','inherit','closed','closed','','56-revision-v1','','','2026-11-21 21:13:11','2026-11-21 21:13:11','',56,'https://rbg-coursework-demo.page.gd/?p=65',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (66,1,'2026-11-21 21:17:43','2026-11-21 21:17:43','','report-a-fly-tip','','publish','closed','closed','','report-a-fly-tip','','','2026-11-22 04:00:01','2026-11-22 04:00:01','',0,'https://rbg-coursework-demo.page.gd/?post_type=forminator_forms&#038;p=66',0,'forminator_forms','',0);
INSERT INTO `wp_posts` VALUES (67,1,'2026-11-21 21:17:51','2026-11-21 21:17:51','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Fly-tipping is rubbish dumped where it should not be, from a single bin bag to a mattress or a pile of builders’ waste. We investigate and clear fly-tips on land we are responsible for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">When we cannot help</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Private land:</strong> the owner or occupier must clear it, including shared alleyways and access roads.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Red routes:</strong> these roads are managed by Transport for London. <a href=\"https://tfl.gov.uk/\">Report it to TfL</a>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Shopping trolleys:</strong> these belong to the shops. Report abandoned trolleys to Trolleywise.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will need</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>exactly where it is: street, nearest house number or landmark, and postcode</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>when you saw it</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>who left it, if you know</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>a photo, if you can take one safely</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Stay safe:</strong> do not touch or move the rubbish, especially if it could be hazardous, such as asbestos, chemicals or needles. Never approach anyone you see fly-tipping.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Tell us about a fly-tip</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[forminator_form id=\"66\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report goes to the Street Services team. Reports of hazardous waste go to the Environmental Crime team.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 5025. You can leave a message at any time, and we reply Monday to Friday, 9am to 5pm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Email <a href=\"mailto:envirocrime@royalgreenwich.gov.uk\">envirocrime@royalgreenwich.gov.uk</a>.</p>\n<!-- /wp:paragraph -->','Report a fly-tip','','inherit','closed','closed','','24-revision-v1','','','2026-11-21 21:17:51','2026-11-21 21:17:51','',24,'https://rbg-coursework-demo.page.gd/?p=67',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (68,1,'2026-11-21 21:19:01','2026-11-21 21:19:01','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#652c95"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#4b1f6f"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#652c95","text":"#ffffff"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#4b1f6f","text":"#ffffff"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #ffdd00 !important; }\\n.rbg-header a:focus-visible { background:#ffdd00; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #ffdd00; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #652c95; transition: background .15s; }\\n.rbg-card:hover { background:#f3eef8; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #652c95; }\\n.rbg-warning { border-left:8px solid #ffdd00; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#ffdd00; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #ffdd00; }\\n\\n/* Forminator */\\n.forminator-ui.forminator-custom-form { font-family: var(--wp--preset--font-family--system-sans) !important; }\\n.forminator-ui .forminator-label, .forminator-ui .forminator-label * { font-size:1.1rem !important; font-weight:700 !important; color:#0b0c0c !important; line-height:1.4 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-description, .forminator-ui .forminator-description * { font-size:1rem !important; color:#505a5f !important; font-family: inherit !important; }\\n.forminator-ui .forminator-input, .forminator-ui .forminator-textarea, .forminator-ui select, .forminator-ui .select2-selection--single { border:2px solid #0b0c0c !important; border-radius:0 !important; font-size:1.1rem !important; min-height:46px !important; background:#fff !important; color:#0b0c0c !important; }\\n.forminator-ui .select2-selection__rendered { font-size:1.1rem !important; color:#0b0c0c !important; line-height:42px !important; }\\n.forminator-ui .forminator-radio, .forminator-ui .forminator-checkbox { font-size:1.1rem !important; }\\n.forminator-ui .forminator-radio-label, .forminator-ui .forminator-checkbox-label { font-size:1.1rem !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio .forminator-radio-bullet { width:28px !important; height:28px !important; border:2px solid #0b0c0c !important; }\\n.forminator-ui .forminator-button-submit { background:#652c95 !important; color:#fff !important; font-size:1.15rem !important; font-weight:700 !important; padding:.85rem 1.75rem !important; border-radius:4px !important; box-shadow:0 3px 0 #2e1145 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#4b1f6f !important; }\\n.forminator-ui .forminator-error-message { font-size:1rem !important; font-weight:700 !important; background:none !important; color:#d4351c !important; padding:0 !important; }\\n.forminator-ui .forminator-has_error .forminator-input, .forminator-ui .forminator-has_error .forminator-textarea { border-color:#d4351c !important; border-width:3px !important; }\\n.forminator-ui .forminator-response-message.forminator-error { border-left:6px solid #d4351c !important; background:#fff5f5 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-field { margin-bottom:.5rem; }\\n.forminator-ui .forminator-row { margin-bottom:1.5rem !important; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"RBG Purple","color":"#652c95"},{"slug":"rbg-purple-dark","name":"RBG Purple Dark","color":"#4b1f6f"},{"slug":"focus-yellow","name":"Focus Yellow","color":"#ffdd00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer Grey","color":"#505a5f"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Light Purple","color":"#f3eef8"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-21 21:19:01','2026-11-21 21:19:01','',5,'https://rbg-coursework-demo.page.gd/?p=68',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (69,1,'2026-11-21 21:19:27','2026-11-21 21:19:27','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#652c95"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#4b1f6f"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#652c95","text":"#ffffff"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#4b1f6f","text":"#ffffff"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #ffdd00 !important; }\\n.rbg-header a:focus-visible { background:#ffdd00; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #ffdd00; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #652c95; transition: background .15s; }\\n.rbg-card:hover { background:#f3eef8; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #652c95; }\\n.rbg-warning { border-left:8px solid #ffdd00; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#ffdd00; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #ffdd00; }\\n\\n/* Forminator */\\n.forminator-ui.forminator-custom-form { font-family: var(--wp--preset--font-family--system-sans) !important; }\\n.forminator-ui .forminator-label, .forminator-ui .forminator-label * { font-size:1.1rem !important; font-weight:700 !important; color:#0b0c0c !important; line-height:1.4 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-description, .forminator-ui .forminator-description * { font-size:1rem !important; color:#505a5f !important; font-family: inherit !important; }\\n.forminator-ui .forminator-input, .forminator-ui .forminator-textarea, .forminator-ui select, .forminator-ui .select2-selection--single { border:2px solid #0b0c0c !important; border-radius:0 !important; font-size:1.1rem !important; min-height:46px !important; background:#fff !important; color:#0b0c0c !important; }\\n.forminator-ui .select2-selection__rendered { font-size:1.1rem !important; color:#0b0c0c !important; line-height:42px !important; }\\n.forminator-ui .forminator-radio, .forminator-ui .forminator-checkbox { font-size:1.1rem !important; }\\n.forminator-ui .forminator-radio-label, .forminator-ui .forminator-checkbox-label { font-size:1.1rem !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio .forminator-radio-bullet { width:26px !important; height:26px !important; min-width:26px !important; flex:0 0 26px !important; border-radius:50% !important; border:2px solid #0b0c0c !important; }\\n.forminator-ui .forminator-button-submit { background:#652c95 !important; color:#fff !important; font-size:1.15rem !important; font-weight:700 !important; padding:.85rem 1.75rem !important; border-radius:4px !important; box-shadow:0 3px 0 #2e1145 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#4b1f6f !important; }\\n.forminator-ui .forminator-error-message { font-size:1rem !important; font-weight:700 !important; background:none !important; color:#d4351c !important; padding:0 !important; }\\n.forminator-ui .forminator-has_error .forminator-input, .forminator-ui .forminator-has_error .forminator-textarea { border-color:#d4351c !important; border-width:3px !important; }\\n.forminator-ui .forminator-response-message.forminator-error { border-left:6px solid #d4351c !important; background:#fff5f5 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-field { margin-bottom:.5rem; }\\n.forminator-ui .forminator-row { margin-bottom:1.5rem !important; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"RBG Purple","color":"#652c95"},{"slug":"rbg-purple-dark","name":"RBG Purple Dark","color":"#4b1f6f"},{"slug":"focus-yellow","name":"Focus Yellow","color":"#ffdd00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer Grey","color":"#505a5f"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Light Purple","color":"#f3eef8"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-21 21:19:27','2026-11-21 21:19:27','',5,'https://rbg-coursework-demo.page.gd/?p=69',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (70,2,'2026-11-22 02:47:36','0000-00-00 00:00:00','','Mattress and bin bags outside 12 Wellington Street','','in-progress','closed','closed','','mattress-and-bin-bags-outside-12-wellington-street','','','2026-11-22 02:47:38','2026-11-22 02:47:38','',0,'https://rbg-coursework-demo.page.gd/?post_type=report&#038;p=70',0,'report','',0);
INSERT INTO `wp_posts` VALUES (71,1,'2026-11-21 21:21:00','2026-11-21 21:21:00','<!-- wp:html -->\n<div class=\"rbg-panel\" style=\"background:#652c95;color:#fff;padding:1.75rem 1.5rem;border-radius:4px\">\n<p style=\"margin:0;font-size:1.6rem;font-weight:700;font-family:var(--wp--preset--font-family--kantumruy-pro)\">Thank you, we have received your report</p>\n<p id=\"rbg-ref-line\" style=\"margin:.75rem 0 0;font-size:1.2rem\">We have emailed your reference number to you.</p>\n</div>\n<script>\ndocument.addEventListener(\'DOMContentLoaded\', function(){\n  var q = new URLSearchParams(location.search), ref = (q.get(\'ref\')||\'\').replace(/[^0-9A-Za-z-]/g,\'\'), type = q.get(\'type\');\n  var prefix = type === \'missed-bin\' ? \'MB-\' : (type === \'fly-tip\' ? \'FT-\' : \'RBG-\');\n  var el = document.getElementById(\'rbg-ref-line\');\n  if (ref && el) { el.innerHTML = \'Your reference number is<br><strong style=\"font-size:2rem;letter-spacing:.05em\">\' + prefix + ref + \'</strong>\'; }\n  var t = document.getElementById(\'rbg-timescale\');\n  if (t && type === \'fly-tip\') t.textContent = \'We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.\';\n  if (t && type === \'missed-bin\') t.textContent = \'We will arrange to collect your bin as soon as possible. Please leave it out until we do.\';\n});\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We have sent a confirmation email with your reference number and a copy of your answers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report has gone straight to the team that deals with it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span id=\"rbg-timescale\">We will deal with your report as quickly as we can.</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you need to contact us about this report, quote your reference number.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Is there anything else?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/parking-transport-and-streets/report-issues-street/\">Report another street problem</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/\">Back to the homepage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Report received','','inherit','closed','closed','','25-revision-v1','','','2026-11-21 21:21:00','2026-11-21 21:21:00','',25,'https://rbg-coursework-demo.page.gd/?p=71',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (72,2,'2026-11-22 02:50:38','0000-00-00 00:00:00','','Possible asbestos sheets behind 40 Powis Street','','assigned','closed','closed','','possible-asbestos-sheets-behind-40-powis-street','','','2026-11-22 02:50:38','2026-11-22 02:50:38','',0,'https://rbg-coursework-demo.page.gd/?post_type=report&#038;p=72',0,'report','',0);
INSERT INTO `wp_posts` VALUES (73,1,'2026-11-21 21:22:27','2026-11-21 21:22:27','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Fly-tipping is rubbish dumped where it should not be, from a single bin bag to a mattress or a pile of builders’ waste. We investigate and clear fly-tips on land we are responsible for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">When we cannot help</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Private land:</strong> the owner or occupier must clear it, including shared alleyways and access roads.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Red routes:</strong> these roads are managed by Transport for London. <a href=\"https://tfl.gov.uk/\">Report it to TfL</a>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Shopping trolleys:</strong> these belong to the shops. Report abandoned trolleys to Trolleywise.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will need</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>exactly where it is: street, nearest house number or landmark, and postcode</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>when you saw it</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>who left it, if you know</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>a photo, if you can take one safely</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Stay safe:</strong> do not touch or move the rubbish, especially if it could be hazardous, such as asbestos, chemicals or needles. Never approach anyone you see fly-tipping.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Tell us about a fly-tip</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[forminator_form id=\"66\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<script>\n(function(){\n  var ref = \'FT-\' + String(Date.now()).slice(-6);\n  function setRef(){ document.querySelectorAll(\'input[name=\"hidden-1\"]\').forEach(function(i){ if (!i.value) i.value = ref; }); }\n  document.addEventListener(\'DOMContentLoaded\', setRef);\n  document.addEventListener(\'submit\', setRef, true);\n  document.addEventListener(\'click\', function(e){ if (e.target.closest && e.target.closest(\'.forminator-button-submit\')) setRef(); }, true);\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report goes to the Street Services team. Reports of hazardous waste go to the Environmental Crime team.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 5025. You can leave a message at any time, and we reply Monday to Friday, 9am to 5pm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Email <a href=\"mailto:envirocrime@royalgreenwich.gov.uk\">envirocrime@royalgreenwich.gov.uk</a>.</p>\n<!-- /wp:paragraph -->','Report a fly-tip','','inherit','closed','closed','','24-revision-v1','','','2026-11-21 21:22:27','2026-11-21 21:22:27','',24,'https://rbg-coursework-demo.page.gd/?p=73',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (74,1,'2026-11-21 21:22:28','2026-11-21 21:22:28','<!-- wp:html -->\n<div class=\"rbg-panel\" style=\"background:#652c95;color:#fff;padding:1.75rem 1.5rem;border-radius:4px\">\n<p style=\"margin:0;font-size:1.6rem;font-weight:700;font-family:var(--wp--preset--font-family--kantumruy-pro)\">Thank you, we have received your report</p>\n<p id=\"rbg-ref-line\" style=\"margin:.75rem 0 0;font-size:1.2rem\">We have emailed your reference number to you.</p>\n</div>\n<script>\ndocument.addEventListener(\'DOMContentLoaded\', function(){\n  var q = new URLSearchParams(location.search), ref = (q.get(\'ref\')||\'\').replace(/[^0-9A-Za-z-]/g,\'\'), type = q.get(\'type\');\n  var prefix = type === \'missed-bin\' ? \'MB-\' : (type === \'fly-tip\' ? \'FT-\' : \'RBG-\');\n  var el = document.getElementById(\'rbg-ref-line\');\n  if (ref && ref !== \'0\' && el) { var shown = /^(FT|MB)-/.test(ref) ? ref : prefix + ref; el.innerHTML = \'Your reference number is<br><strong style=\"font-size:2rem;letter-spacing:.05em\">\' + shown + \'</strong>\'; }\n  var t = document.getElementById(\'rbg-timescale\');\n  if (t && type === \'fly-tip\') t.textContent = \'We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.\';\n  if (t && type === \'missed-bin\') t.textContent = \'We will arrange to collect your bin as soon as possible. Please leave it out until we do.\';\n});\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We have sent a confirmation email with your reference number and a copy of your answers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report has gone straight to the team that deals with it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span id=\"rbg-timescale\">We will deal with your report as quickly as we can.</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you need to contact us about this report, quote your reference number.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Is there anything else?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/parking-transport-and-streets/report-issues-street/\">Report another street problem</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/\">Back to the homepage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Report received','','inherit','closed','closed','','25-revision-v1','','','2026-11-21 21:22:28','2026-11-21 21:22:28','',25,'https://rbg-coursework-demo.page.gd/?p=74',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (75,2,'2026-11-21 21:24:21','2026-11-21 21:24:21','','Sofa and chairs dumped on Trafalgar Road','','trash','closed','closed','','sofa-and-chairs-dumped-on-trafalgar-road__trashed','','','2026-11-21 21:24:21','2026-11-21 21:24:21','',0,'https://rbg-coursework-demo.page.gd/?post_type=report&#038;p=75',0,'report','',0);
INSERT INTO `wp_posts` VALUES (76,1,'2026-11-21 21:23:16','2026-11-21 21:23:16','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Fly-tipping is rubbish dumped where it should not be, from a single bin bag to a mattress or a pile of builders’ waste. We investigate and clear fly-tips on land we are responsible for.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">When we cannot help</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Private land:</strong> the owner or occupier must clear it, including shared alleyways and access roads.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Red routes:</strong> these roads are managed by Transport for London. <a href=\"https://tfl.gov.uk/\">Report it to TfL</a>.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Shopping trolleys:</strong> these belong to the shops. Report abandoned trolleys to Trolleywise.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What you will need</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>what has been dumped</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>exactly where it is: street, nearest house number or landmark, and postcode</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>when you saw it</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>who left it, if you know</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>a photo, if you can take one safely</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:group {\"className\":\"rbg-warning\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-warning has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Stay safe:</strong> do not touch or move the rubbish, especially if it could be hazardous, such as asbestos, chemicals or needles. Never approach anyone you see fly-tipping.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"anchor\":\"form\"} -->\n<h2 id=\"form\" class=\"wp-block-heading\">Tell us about a fly-tip</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[forminator_form id=\"66\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<script>\n(function(){\n  var ref = \'FT-\' + String(Date.now()).slice(-6);\n  function setRef(){ document.querySelectorAll(\'input[name=\"text-3\"]\').forEach(function(i){ if (!i.value) i.value = ref; }); }\n  document.addEventListener(\'DOMContentLoaded\', setRef);\n  document.addEventListener(\'submit\', setRef, true);\n  document.addEventListener(\'click\', function(e){ if (e.target.closest && e.target.closest(\'.forminator-button-submit\')) setRef(); }, true);\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We will email you straight away with your reference number.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report goes to the Street Services team. Reports of hazardous waste go to the Environmental Crime team.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Other ways to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Call 020 8921 5025. You can leave a message at any time, and we reply Monday to Friday, 9am to 5pm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Email <a href=\"mailto:envirocrime@royalgreenwich.gov.uk\">envirocrime@royalgreenwich.gov.uk</a>.</p>\n<!-- /wp:paragraph -->','Report a fly-tip','','inherit','closed','closed','','24-revision-v1','','','2026-11-21 21:23:16','2026-11-21 21:23:16','',24,'https://rbg-coursework-demo.page.gd/?p=76',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (77,1,'2026-11-21 21:23:16','2026-11-21 21:23:16','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#652c95"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#4b1f6f"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#652c95","text":"#ffffff"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#4b1f6f","text":"#ffffff"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #ffdd00 !important; }\\n.rbg-header a:focus-visible { background:#ffdd00; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #ffdd00; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #652c95; transition: background .15s; }\\n.rbg-card:hover { background:#f3eef8; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #652c95; }\\n.rbg-warning { border-left:8px solid #ffdd00; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#ffdd00; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#ffdd00 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #ffdd00; }\\n\\n/* Forminator */\\n.forminator-ui.forminator-custom-form { font-family: var(--wp--preset--font-family--system-sans) !important; }\\n.forminator-ui .forminator-label, .forminator-ui .forminator-label * { font-size:1.1rem !important; font-weight:700 !important; color:#0b0c0c !important; line-height:1.4 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-description, .forminator-ui .forminator-description * { font-size:1rem !important; color:#505a5f !important; font-family: inherit !important; }\\n.forminator-ui .forminator-input, .forminator-ui .forminator-textarea, .forminator-ui select, .forminator-ui .select2-selection--single { border:2px solid #0b0c0c !important; border-radius:0 !important; font-size:1.1rem !important; min-height:46px !important; background:#fff !important; color:#0b0c0c !important; }\\n.forminator-ui .select2-selection__rendered { font-size:1.1rem !important; color:#0b0c0c !important; line-height:42px !important; }\\n.forminator-ui .forminator-radio, .forminator-ui .forminator-checkbox { font-size:1.1rem !important; }\\n.forminator-ui .forminator-radio-label, .forminator-ui .forminator-checkbox-label { font-size:1.1rem !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio .forminator-radio-bullet { width:26px !important; height:26px !important; min-width:26px !important; flex:0 0 26px !important; border-radius:50% !important; border:2px solid #0b0c0c !important; }\\n.forminator-ui .forminator-button-submit { background:#652c95 !important; color:#fff !important; font-size:1.15rem !important; font-weight:700 !important; padding:.85rem 1.75rem !important; border-radius:4px !important; box-shadow:0 3px 0 #2e1145 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#4b1f6f !important; }\\n.forminator-ui .forminator-error-message { font-size:1rem !important; font-weight:700 !important; background:none !important; color:#d4351c !important; padding:0 !important; }\\n.forminator-ui .forminator-has_error .forminator-input, .forminator-ui .forminator-has_error .forminator-textarea { border-color:#d4351c !important; border-width:3px !important; }\\n.forminator-ui .forminator-response-message.forminator-error { border-left:6px solid #d4351c !important; background:#fff5f5 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-field { margin-bottom:.5rem; }\\n.forminator-ui .forminator-row { margin-bottom:1.5rem !important; }\\n\\n.forminator-ui .rbg-ref-field, .forminator-ui .forminator-col:has(.rbg-ref-field) { display:none !important; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"RBG Purple","color":"#652c95"},{"slug":"rbg-purple-dark","name":"RBG Purple Dark","color":"#4b1f6f"},{"slug":"focus-yellow","name":"Focus Yellow","color":"#ffdd00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer Grey","color":"#505a5f"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Light Purple","color":"#f3eef8"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-21 21:23:16','2026-11-21 21:23:16','',5,'https://rbg-coursework-demo.page.gd/?p=77',0,'revision','',0);
