INSERT INTO `wp_posts` VALUES (88,1,'2026-11-22 02:50:38','2026-11-22 02:50:38','','Possible asbestos sheets behind 40 Powis Street','','inherit','closed','closed','','72-revision-v1','','','2026-11-22 02:50:38','2026-11-22 02:50:38','',72,'https://rbg-coursework-demo.page.gd/?p=88',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (89,4,'2026-11-22 17:43:53','2026-11-22 17:43:53','<!-- wp:paragraph -->\n<p>Join one of our community litter picks this spring and help keep Royal Greenwich clean.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We provide gloves, bags and litter pickers, and we collect the full bags afterwards. Events take place on Saturday mornings in parks across the borough.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How to take part</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Email the Street Services team to book a place. If you spot fly-tipping while you are out, <a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">report it online</a>.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Volunteer for a community litter pick this spring','Help keep Royal Greenwich clean at a Saturday morning litter pick.','publish','closed','closed','','volunteer-for-a-community-litter-pick-this-spring','','','2026-11-22 17:44:51','2026-11-22 17:44:51','',0,'https://rbg-coursework-demo.page.gd/?p=89&#038;preview=true&#038;preview_id=89',0,'post','',0);
