"/recycling-and-rubbish/\">Recycling and rubbish</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bin days, missed bins, recycling and household waste.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\"><a href=\"/parking-transport-and-streets/\">Parking, transport and streets</a></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Report street problems, parking permits and fines.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Council Tax</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pay, check your bill or apply for a discount. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Housing</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Repairs, rent and finding a home. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Adult care and health</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Support to live independently. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"className\":\"rbg-card\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.25rem\",\"right\":\"1.25rem\"},\"blockGap\":\"0.5rem\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-card has-light-grey-background-color has-background\" style=\"min-height:100%;padding-top:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;padding-left:1.25rem\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"1.25rem\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:1.25rem\">Schools and education</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>School places, term dates and free school meals. <em>(not in this demo)</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-top:var(--wp--preset--spacing--50)\">Latest news</h2>\n<!-- /wp:heading -->\n\n<!-- wp:query {\"queryId\":2,\"query\":{\"perPage\":3,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"inherit\":false,\"excludeCurrent\":null}} -->\n<div class=\"wp-block-query\"><!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"style\":{\"typography\":{\"fontSize\":\"1.2rem\"}}} /-->\n\n<!-- wp:post-date {\"format\":\"j F Y\",\"metadata\":{\"bindings\":{\"datetime\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"date\"}}}},\"style\":{\"typography\":{\"fontSize\":\"0.95rem\"},\"color\":{\"text\":\"#505a5f\"}}} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/news/\">See all news</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:heading {\"style\":{\"typography\":{\"fontSize\":\"1.4rem\"}}} -->\n<h2 class=\"wp-block-heading\" style=\"font-size:1.4rem\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Phone 020 8854 8888, or visit us at The Woolwich Centre, Wellington Street, SE18 6HQ. <a href=\"/contact-us/\">See all ways to contact us</a>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Home','','inherit','closed','closed','','17-revision-v1','','','2026-11-22 02:58:38','2026-11-22 02:58:38','',17,'https://rbg-coursework-demo.page.gd/?p=93',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (94,1,'2026-11-22 03:47:37','2026-11-22 03:47:37','','istockphoto-2194640141-612x612','Trash can with pile of garbage bags for scattered trash concept illustration clip art','inherit','closed','closed','','istockphoto-2194640141-612x612','','','2026-11-22 03:47:37','2026-11-22 03:47:37','',0,'https://rbg-coursework-demo.page.gd/wp-content/uploads/2026/11/istockphoto-2194640141-612x612-1.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (95,1,'2026-11-22 03:56:58','2026-11-22 03:56:58','','Fly-tipping news image','','inherit','closed','closed','','fly-tipping-news-image','','','2026-11-22 03:56:58','2026-11-22 03:56:58','',0,'https://rbg-coursework-demo.page.gd/wp-content/uploads/2026/11/news-flytipping-rubbish.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (96,1,'2026-11-22 03:56:58','2026-11-22 03:56:58','<!-- wp:paragraph -->\n<p>Residents can now report fly-tipping on our website in a couple of minutes, without creating an account.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The new form asks what has been dumped and where, and lets you add a photo. You get a reference number straight away by email, and your report goes directly to the right team. Reports of hazardous waste, such as asbestos or chemicals, are sent to the Environmental Crime team.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How to report</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Go to <a href=\"/parking-transport-and-streets/report-issues-street/report-fly-tip/\">Report a fly-tip</a>. We aim to clear fly-tips within 48 hours.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Report fly-tipping in under two minutes with our new online form','Residents can now report dumped rubbish, add a photo and get a reference number straight away.','inherit','closed','closed','','47-revision-v1','','','2026-11-22 03:56:58','2026-11-22 03:56:58','',47,'https://rbg-coursework-demo.page.gd/?p=96',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (97,1,'2026-11-22 03:56:58','2026-11-22 03:56:58','','Bin collection changes news image','','inherit','closed','closed','','bin-collection-changes-news-image','','','2026-11-22 03:56:58','2026-11-22 03:56:58','',0,'https://rbg-coursework-demo.page.gd/wp-content/uploads/2026/11/news-collection-calendar.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (98,1,'2026-11-22 03:56:59','2026-11-22 03:56:59','<!-- wp:paragraph -->\n<p>Bin collections will move over Christmas and New Year because of the bank holidays.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Use <a href=\"/recycling-and-rubbish/bins-and-collections/find-your-bin-collection-day/\">Find your bin collection day</a> to check when we will collect your bins. Put your bins out by 6am on your collection day.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Extra recycling</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Flatten cardboard boxes and put them next to your blue top bin. We will take them away with your recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Christmas and New Year bin collection changes','Bin collections will move over the festive period. Check your day before you put your bins out.','inherit','closed','closed','','48-revision-v1','','','2026-11-22 03:56:59','2026-11-22 03:56:59','',48,'https://rbg-coursework-demo.page.gd/?p=98',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (99,1,'2026-11-22 03:56:59','2026-11-22 03:56:59','','Garden waste collections news image','','inherit','closed','closed','','garden-waste-collections-news-image','','','2026-11-22 03:56:59','2026-11-22 03:56:59','',0,'https://rbg-coursework-demo.page.gd/wp-content/uploads/2026/11/news-garden-waste-bins.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (100,1,'2026-11-22 03:56:59','2026-11-22 03:56:59','<!-- wp:paragraph -->\n<p>Garden waste collections are changing to every two weeks over the winter, when less garden waste is produced.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Your black top and blue top bin collections are not changing. If we miss your bin, you can <a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">report a missed bin</a> online.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><em>This is a sample news story written for the coursework demo. It is not a real council announcement.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Green top garden waste bins back to fortnightly collections','Garden waste collections return to every two weeks over the winter months.','inherit','closed','closed','','49-revision-v1','','','2026-11-22 03:56:59','2026-11-22 03:56:59','',49,'https://rbg-coursework-demo.page.gd/?p=100',0,'revision','',0);
