INSERT INTO `wp_posts` VALUES (104,1,'2026-11-22 03:59:38','2026-11-22 03:59:38','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#7a5c00"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#0b0c0c"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#0b0c0c","text":"#d4af37"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#d4af37","text":"#0b0c0c"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #d4af37 !important; }\\n.rbg-header a:focus-visible { background:#d4af37; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #d4af37; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#d4af37 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #d4af37; transition: background .15s; }\\n.rbg-card:hover { background:#faf6e9; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #d4af37; }\\n.rbg-warning { border-left:8px solid #d4af37; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#d4af37; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#d4af37 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #d4af37; }\\n\\n/* Forminator */\\n.forminator-ui.forminator-custom-form { font-family: var(--wp--preset--font-family--system-sans) !important; }\\n.forminator-ui .forminator-label, .forminator-ui .forminator-label * { font-size:1.1rem !important; font-weight:700 !important; color:#0b0c0c !important; line-height:1.4 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-description, .forminator-ui .forminator-description * { font-size:1rem !important; color:#505a5f !important; font-family: inherit !important; }\\n.forminator-ui .forminator-input, .forminator-ui .forminator-textarea, .forminator-ui select, .forminator-ui .select2-selection--single { border:2px solid #0b0c0c !important; border-radius:0 !important; font-size:1.1rem !important; min-height:46px !important; background:#fff !important; color:#0b0c0c !important; }\\n.forminator-ui .select2-selection__rendered { font-size:1.1rem !important; color:#0b0c0c !important; line-height:42px !important; }\\n.forminator-ui .forminator-radio, .forminator-ui .forminator-checkbox { font-size:1.1rem !important; }\\n.forminator-ui .forminator-radio-label, .forminator-ui .forminator-checkbox-label { font-size:1.1rem !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio .forminator-radio-bullet { width:26px !important; height:26px !important; min-width:26px !important; flex:0 0 26px !important; border-radius:50% !important; border:2px solid #0b0c0c !important; }\\n.forminator-ui .forminator-button-submit { background:#d4af37 !important; color:#fff !important; font-size:1.15rem !important; font-weight:700 !important; padding:.85rem 1.75rem !important; border-radius:4px !important; box-shadow:0 3px 0 #000000 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#d4af37 !important; }\\n.forminator-ui .forminator-error-message { font-size:1rem !important; font-weight:700 !important; background:none !important; color:#d4351c !important; padding:0 !important; }\\n.forminator-ui .forminator-has_error .forminator-input, .forminator-ui .forminator-has_error .forminator-textarea { border-color:#d4351c !important; border-width:3px !important; }\\n.forminator-ui .forminator-response-message.forminator-error { border-left:6px solid #d4351c !important; background:#fff5f5 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-field { margin-bottom:.5rem; }\\n.forminator-ui .forminator-row { margin-bottom:1.5rem !important; }\\n\\n.forminator-ui .rbg-ref-field, .forminator-ui .forminator-col:has(.rbg-ref-field) { display:none !important; }\\n\\n/* Black and gold theme */\\n.rbg-header .wp-block-site-title, .rbg-header .wp-block-site-title a { color:#d4af37 !important; }\\n.rbg-header .wp-block-navigation a:hover, .rbg-footer a:hover { color:#d4af37 !important; }\\n.rbg-hero h1.has-white-color { color:#d4af37 !important; }\\n.rbg-footer { border-top:6px solid #d4af37; }\\n.rbg-footer h2.has-white-color { color:#d4af37 !important; }\\n.rbg-footer .wp-block-separator { background-color:#d4af37 !important; color:#d4af37 !important; opacity:.6; }\\n.rbg-warning { border-left-color:#0b0c0c !important; }\\n.rbg-card h3 a { color:#0b0c0c; text-decoration-color:#d4af37; text-decoration-thickness:3px; }\\n.rbg-card h3 a:hover { color:#7a5c00; }\\n.wp-block-button.is-style-outline .wp-block-button__link { border:2px solid #0b0c0c; color:#0b0c0c; background:transparent; }\\n.wp-block-button.is-style-outline .wp-block-button__link:hover { background:#d4af37; color:#0b0c0c; }\\n.forminator-ui .forminator-button-submit { background:#0b0c0c !important; color:#d4af37 !important; box-shadow:0 3px 0 #d4af37 !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#d4af37 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio input:checked + .forminator-radio-bullet, .forminator-ui .forminator-checkbox input:checked + .forminator-checkbox-box { border-color:#0b0c0c !important; }\\n.wp-block-query .wp-block-post-title a { color:#0b0c0c; text-decoration-color:#d4af37; }\\n.wp-block-query .wp-block-post-title a:hover { color:#7a5c00; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"Black","color":"#0b0c0c"},{"slug":"rbg-purple-dark","name":"Charcoal","color":"#1f1f1f"},{"slug":"focus-yellow","name":"Gold","color":"#d4af37"},{"slug":"dark-gold","name":"Dark gold","color":"#7a5c00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer black","color":"#0b0c0c"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Cream","color":"#faf6e9"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-22 03:59:38','2026-11-22 03:59:38','',5,'https://rbg-coursework-demo.page.gd/?p=104',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (105,1,'2026-11-22 04:00:00','2026-11-22 04:00:00','<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\">Enter your postcode to check which day we collect your rubbish and recycling.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"rbg-binday\">\n<label for=\"rbg-postcode\" style=\"display:block;font-weight:700;font-size:1.15rem\">Enter your postcode</label>\n<p id=\"rbg-postcode-hint\" style=\"margin:.25rem 0 .5rem;color:#505a5f\">For example, SE10 9GB</p>\n<div style=\"display:flex;flex-wrap:wrap;gap:.5rem;align-items:stretch\">\n<input id=\"rbg-postcode\" type=\"text\" autocomplete=\"postal-code\" spellcheck=\"false\" aria-describedby=\"rbg-postcode-hint\" style=\"font-size:1.1rem;padding:.55rem .7rem;border:2px solid #0b0c0c;min-height:44px;max-width:12rem;width:100%\">\n<button type=\"button\" id=\"rbg-find\" class=\"wp-element-button\" style=\"min-height:44px\">Find my bin day</button>\n</div>\n<div id=\"rbg-result\" role=\"status\" aria-live=\"polite\" style=\"margin-top:1rem\"></div>\n</div>\n<script>\n(function(){\n  var days = {SE2:\'Monday\', SE3:\'Tuesday\', SE7:\'Wednesday\', SE9:\'Thursday\', SE10:\'Friday\', SE12:\'Thursday\', SE18:\'Monday\', SE28:\'Tuesday\'};\n  var input = document.getElementById(\'rbg-postcode\'), out = document.getElementById(\'rbg-result\');\n  if (!input) return;\n  function find(){\n    var pc = (input.value || \'\').toUpperCase().replace(/\\s+/g,\'\');\n    var m = pc.match(/^(SE\\d{1,2})(\\d[A-Z]{2})?$/);\n    if (!pc) { out.innerHTML = \'<p style=\"color:#d4351c;font-weight:700\">Enter a postcode</p>\'; input.focus(); return; }\n    var district = m ? m[1] : null;\n    if (district && days[district]) {\n      out.innerHTML = \'<div style=\"background:#faf6e9;border-left:8px solid #d4af37;padding:1rem 1.25rem\"><p style=\"margin:0;font-size:1.25rem\"><strong>\' + district + \': your bins are collected on \' + days[district] + \'</strong></p><p style=\"margin:.5rem 0 0\">Put your bins out by 6am. We collect between 6am and 8pm. <a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a></p></div>\';\n    } else {\n      out.innerHTML = \'<p><strong>We could not find that postcode in Royal Greenwich.</strong> Check it and try again, or <a href=\"/contact-us/\">contact us</a>.</p>\';\n    }\n  }\n  document.getElementById(\'rbg-find\').addEventListener(\'click\', find);\n  input.addEventListener(\'keydown\', function(e){ if (e.key === \'Enter\') { e.preventDefault(); find(); } });\n})();\n</script>\n<!-- /wp:html -->\n\n<!-- wp:group {\"className\":\"rbg-callout\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.25rem\",\"bottom\":\"1.25rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"},\"margin\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group rbg-callout has-light-grey-background-color has-background\" style=\"margin-top:1.5rem;margin-bottom:1.5rem;padding-top:1.25rem;padding-right:1.5rem;padding-bottom:1.25rem;padding-left:1.5rem\"><!-- wp:paragraph -->\n<p><strong>Demo data:</strong> this lookup uses sample collection days by postcode area. The live service would check your exact address against the council’s collection rounds.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Collection days by area (sample)</h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"hasFixedLayout\":false} -->\n<figure class=\"wp-block-table\"><table><thead><tr><th>Postcode area</th><th>Areas covered</th><th>Collection day</th></tr></thead><tbody><tr><td>SE2</td><td>Abbey Wood</td><td>Monday</td></tr><tr><td>SE3</td><td>Blackheath, Kidbrooke</td><td>Tuesday</td></tr><tr><td>SE7</td><td>Charlton</td><td>Wednesday</td></tr><tr><td>SE9</td><td>Eltham, Mottingham</td><td>Thursday</td></tr><tr><td>SE10</td><td>Greenwich, Greenwich Peninsula</td><td>Friday</td></tr><tr><td>SE12</td><td>Lee, Grove Park (Greenwich part)</td><td>Thursday</td></tr><tr><td>SE18</td><td>Woolwich, Plumstead, Shooters Hill</td><td>Monday</td></tr><tr><td>SE28</td><td>Thamesmead</td><td>Tuesday</td></tr></tbody></table><figcaption class=\"wp-element-caption\">Sample bin collection days for this demo</figcaption></figure>\n<!-- /wp:table -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Before your collection</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Put your bins out by 6am on your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>We collect between 6am and 8pm, so the time can change from week to week.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you live in a flat or on an estate, ask your caretaker or managing agent for your collection day.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Collections that fall on a bank holiday move to a new date.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">If we did not empty your bin</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><a href=\"/recycling-and-rubbish/bins-and-collections/report-missed-bin/\">Report a missed bin</a> by midnight on the day after your collection day.</p>\n<!-- /wp:paragraph -->','Find your bin collection day','','inherit','closed','closed','','20-revision-v1','','','2026-11-22 04:00:00','2026-11-22 04:00:00','',20,'https://rbg-coursework-demo.page.gd/?p=105',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (106,1,'2026-11-22 04:00:00','2026-11-22 04:00:00','<!-- wp:html -->\n<div class=\"rbg-panel\" style=\"background:#0b0c0c;color:#fff;padding:1.75rem 1.5rem;border-radius:4px;border-top:6px solid #d4af37\">\n<p style=\"margin:0;font-size:1.6rem;font-weight:700;font-family:var(--wp--preset--font-family--kantumruy-pro);color:#d4af37\">Thank you, we have received your report</p>\n<p id=\"rbg-ref-line\" style=\"margin:.75rem 0 0;font-size:1.2rem\">We have emailed your reference number to you.</p>\n</div>\n<script>\ndocument.addEventListener(\'DOMContentLoaded\', function(){\n  var q = new URLSearchParams(location.search), ref = (q.get(\'ref\')||\'\').replace(/[^0-9A-Za-z-]/g,\'\'), type = q.get(\'type\');\n  var prefix = type === \'missed-bin\' ? \'MB-\' : (type === \'fly-tip\' ? \'FT-\' : \'RBG-\');\n  var el = document.getElementById(\'rbg-ref-line\');\n  if (ref && ref !== \'0\' && el) { var shown = /^(FT|MB)-/.test(ref) ? ref : prefix + ref; el.innerHTML = \'Your reference number is<br><strong style=\"font-size:2rem;letter-spacing:.05em;color:#d4af37\">\' + shown + \'</strong>\'; }\n  var t = document.getElementById(\'rbg-timescale\');\n  if (t && type === \'fly-tip\') t.textContent = \'We aim to clear fly-tips within 48 hours. Hazardous waste can take longer.\';\n  if (t && type === \'missed-bin\') t.textContent = \'We will arrange to collect your bin as soon as possible. Please leave it out until we do.\';\n});\n</script>\n<!-- /wp:html -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What happens next</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li>We have sent a confirmation email with your reference number and a copy of your answers.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Your report has gone straight to the team that deals with it.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><span id=\"rbg-timescale\">We will deal with your report as quickly as we can.</span></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>If you need to contact us about this report, quote your reference number.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Is there anything else?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"/parking-transport-and-streets/report-issues-street/\">Report another street problem</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/\">Back to the homepage</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Report received','','inherit','closed','closed','','25-revision-v1','','','2026-11-22 04:00:00','2026-11-22 04:00:00','',25,'https://rbg-coursework-demo.page.gd/?p=106',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (107,1,'2026-11-22 04:00:00','2026-11-22 04:00:00','<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-header\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff\"}}}},\"backgroundColor\":\"rbg-purple\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull rbg-header has-white-color has-rbg-purple-background-color has-text-color has-background has-link-color\" style=\"padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|30\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:site-title {\"level\":0,\"style\":{\"typography\":{\"fontWeight\":\"700\",\"fontSize\":\"1.65rem\",\"lineHeight\":\"1.1\"}},\"textColor\":\"white\",\"fontFamily\":\"kantumruy-pro\"} /-->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:navigation {\"ref\":50,\"textColor\":\"white\",\"overlayBackgroundColor\":\"rbg-purple-dark\",\"overlayTextColor\":\"white\",\"style\":{\"typography\":{\"fontWeight\":\"600\",\"fontSize\":\"1.05rem\"},\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"right\",\"flexWrap\":\"wrap\"}} /-->\n\n<!-- wp:search {\"label\":\"Search\",\"showLabel\":false,\"placeholder\":\"Search\",\"width\":260,\"widthUnit\":\"px\",\"buttonText\":\"Search\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"rbg-demo-banner\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0.6rem\",\"bottom\":\"0.6rem\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"light-grey\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull rbg-demo-banner has-light-grey-background-color has-background\" style=\"padding-top:0.6rem;padding-right:var(--wp--preset--spacing--40);padding-bottom:0.6rem;padding-left:var(--wp--preset--spacing--40)\"><!-- wp:paragraph {\"align\":\"left\",\"className\":\"alignwide\",\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-left alignwide has-small-font-size\"><strong><mark style=\"background-color:#0b0c0c;color:#d4af37\" class=\"has-inline-color\"> DEMO </mark></strong> This is a student coursework prototype built in WordPress. It is not the official Royal Borough of Greenwich website.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','Header','','inherit','closed','closed','','52-revision-v1','','','2026-11-22 04:00:00','2026-11-22 04:00:00','',52,'https://rbg-coursework-demo.page.gd/?p=107',0,'revision','',0);
