INSERT INTO `wp_posts` VALUES (113,1,'2026-11-22 16:33:09','2026-11-22 16:33:09','{"styles":{"color":{"background":"#ffffff","text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--system-sans)","fontSize":"1.125rem","fontWeight":"400","lineHeight":"1.55","letterSpacing":"normal"},"elements":{"link":{"color":{"text":"#7a5c00"},"typography":{"textDecoration":"underline"},":hover":{"color":{"text":"#0b0c0c"},"typography":{"textDecoration":"underline"}}},"heading":{"color":{"text":"#0b0c0c"},"typography":{"fontFamily":"var(--wp--preset--font-family--kantumruy-pro)","fontWeight":"700","letterSpacing":"normal","lineHeight":"1.2"}},"h1":{"typography":{"fontSize":"clamp(2rem, 4vw, 2.75rem)"}},"h2":{"typography":{"fontSize":"clamp(1.5rem, 2.6vw, 1.875rem)"}},"h3":{"typography":{"fontSize":"1.3rem"}},"button":{"color":{"background":"#0b0c0c","text":"#d4af37"},"border":{"radius":"4px"},"typography":{"fontWeight":"600","fontSize":"1.05rem","fontFamily":"var(--wp--preset--font-family--system-sans)"},":hover":{"color":{"background":"#d4af37","text":"#0b0c0c"}}}},"css":"\\n/* Accessibility: thick black-and-yellow focus ring, visible on white and on purple */\\n:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: 3px solid #0b0c0c !important; outline-offset: 0 !important; box-shadow: 0 0 0 6px #d4af37 !important; }\\n.rbg-header a:focus-visible { background:#d4af37; color:#0b0c0c !important; }\\n/* Purple header */\\n.rbg-header { border-bottom: 6px solid #d4af37; }\\n.rbg-header .wp-block-site-title a { color:#fff; text-decoration:none; }\\n.rbg-header .wp-block-navigation a { text-decoration:none; }\\n.rbg-header .wp-block-navigation a:hover { text-decoration:underline; text-underline-offset:4px; }\\n.rbg-header .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:44px; }\\n.rbg-header .wp-block-search__button { background:#d4af37 !important; color:#0b0c0c !important; border-radius:0; margin-left:0; min-height:44px; font-weight:600; }\\n/* Demo banner */\\n.rbg-demo-banner { font-size:0.95rem; }\\n/* Breadcrumbs */\\n.rbg-breadcrumbs, .yoast-breadcrumbs { font-size:0.95rem; }\\n/* Task cards and popular tasks */\\n.rbg-card { border-top:5px solid #d4af37; transition: background .15s; }\\n.rbg-card:hover { background:#faf6e9; }\\n.rbg-card h3 a, .rbg-card h2 a { text-decoration:underline; text-underline-offset:3px; }\\n.rbg-link-list { list-style:none; padding-left:0; }\\n.rbg-link-list li { border-bottom:1px solid #b1b4b6; padding: .8rem 0; }\\n.rbg-link-list li a { font-weight:600; font-size:1.15rem; }\\n.rbg-callout { border-left:8px solid #d4af37; }\\n.rbg-warning { border-left:8px solid #d4af37; }\\n.rbg-notbuilt { opacity:.75; }\\n/* Buttons: large tap targets */\\n.wp-block-button__link { min-height:44px; padding: .75rem 1.25rem; }\\n/* Tables */\\n.wp-block-table table { border-collapse: collapse; }\\n.wp-block-table th { background:#f3f2f1; text-align:left; }\\n.wp-block-table td, .wp-block-table th { border:1px solid #b1b4b6; padding:.6rem .8rem; }\\n/* Footer */\\n.rbg-footer a { color:#fff; }\\n.rbg-footer a:hover { color:#d4af37; }\\n/* Reference panel on confirmation page */\\n.rbg-panel { text-align:center; }\\n\\n/* Hero search on purple */\\n.rbg-hero-search .wp-block-search__label { color:#fff; font-weight:600; }\\n.rbg-hero-search .wp-block-search__input { border:2px solid #0b0c0c; border-radius:0; min-height:52px; font-size:1.1rem; }\\n.rbg-hero-search .wp-block-search__button { background:#d4af37 !important; color:#0b0c0c !important; border-radius:0; min-height:52px; margin-left:0; font-weight:700; padding: 0 1.5rem; }\\n/* Equal-height cards */\\n.rbg-home .wp-block-column \\u003E .rbg-card { height:100%; }\\n/* Form inputs site-wide */\\n.rbg-binday input:focus-visible { outline:3px solid #0b0c0c; box-shadow:0 0 0 6px #d4af37; }\\n\\n/* Forminator */\\n.forminator-ui.forminator-custom-form { font-family: var(--wp--preset--font-family--system-sans) !important; }\\n.forminator-ui .forminator-label, .forminator-ui .forminator-label * { font-size:1.1rem !important; font-weight:700 !important; color:#0b0c0c !important; line-height:1.4 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-description, .forminator-ui .forminator-description * { font-size:1rem !important; color:#505a5f !important; font-family: inherit !important; }\\n.forminator-ui .forminator-input, .forminator-ui .forminator-textarea, .forminator-ui select, .forminator-ui .select2-selection--single { border:2px solid #0b0c0c !important; border-radius:0 !important; font-size:1.1rem !important; min-height:46px !important; background:#fff !important; color:#0b0c0c !important; }\\n.forminator-ui .select2-selection__rendered { font-size:1.1rem !important; color:#0b0c0c !important; line-height:42px !important; }\\n.forminator-ui .forminator-radio, .forminator-ui .forminator-checkbox { font-size:1.1rem !important; }\\n.forminator-ui .forminator-radio-label, .forminator-ui .forminator-checkbox-label { font-size:1.1rem !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio .forminator-radio-bullet { width:26px !important; height:26px !important; min-width:26px !important; flex:0 0 26px !important; border-radius:50% !important; border:2px solid #0b0c0c !important; }\\n.forminator-ui .forminator-button-submit { background:#d4af37 !important; color:#fff !important; font-size:1.15rem !important; font-weight:700 !important; padding:.85rem 1.75rem !important; border-radius:4px !important; box-shadow:0 3px 0 #000000 !important; font-family: inherit !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#d4af37 !important; }\\n.forminator-ui .forminator-error-message { font-size:1rem !important; font-weight:700 !important; background:none !important; color:#d4351c !important; padding:0 !important; }\\n.forminator-ui .forminator-has_error .forminator-input, .forminator-ui .forminator-has_error .forminator-textarea { border-color:#d4351c !important; border-width:3px !important; }\\n.forminator-ui .forminator-response-message.forminator-error { border-left:6px solid #d4351c !important; background:#fff5f5 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-field { margin-bottom:.5rem; }\\n.forminator-ui .forminator-row { margin-bottom:1.5rem !important; }\\n\\n.forminator-ui .rbg-ref-field, .forminator-ui .forminator-col:has(.rbg-ref-field) { display:none !important; }\\n\\n/* Black and gold theme */\\n.rbg-header .wp-block-site-title, .rbg-header .wp-block-site-title a { color:#d4af37 !important; }\\n.rbg-header .wp-block-navigation a:hover, .rbg-footer a:hover { color:#d4af37 !important; }\\n.rbg-hero h1.has-white-color { color:#d4af37 !important; }\\n.rbg-footer { border-top:6px solid #d4af37; }\\n.rbg-footer h2.has-white-color { color:#d4af37 !important; }\\n.rbg-footer .wp-block-separator { background-color:#d4af37 !important; color:#d4af37 !important; opacity:.6; }\\n.rbg-warning { border-left-color:#0b0c0c !important; }\\n.rbg-card h3 a { color:#0b0c0c; text-decoration-color:#d4af37; text-decoration-thickness:3px; }\\n.rbg-card h3 a:hover { color:#7a5c00; }\\n.wp-block-button.is-style-outline .wp-block-button__link { border:2px solid #0b0c0c; color:#0b0c0c; background:transparent; }\\n.wp-block-button.is-style-outline .wp-block-button__link:hover { background:#d4af37; color:#0b0c0c; }\\n.forminator-ui .forminator-button-submit { background:#0b0c0c !important; color:#d4af37 !important; box-shadow:0 3px 0 #d4af37 !important; }\\n.forminator-ui .forminator-button-submit:hover { background:#d4af37 !important; color:#0b0c0c !important; }\\n.forminator-ui .forminator-radio input:checked + .forminator-radio-bullet, .forminator-ui .forminator-checkbox input:checked + .forminator-checkbox-box { border-color:#0b0c0c !important; }\\n.wp-block-query .wp-block-post-title a { color:#0b0c0c; text-decoration-color:#d4af37; }\\n.wp-block-query .wp-block-post-title a:hover { color:#7a5c00; }\\n\\n/* Hide Forminator\'s admin-only \\"Edit form\\" shortcut on the public pages */\\nsmall:has(\\u003E .forminator-module-edit-link), .forminator-module-edit-link { display:none !important; }\\n"},"settings":{"layout":{"contentSize":"760px","wideSize":"1200px"},"color":{"palette":{"custom":[{"slug":"rbg-purple","name":"Black","color":"#0b0c0c"},{"slug":"rbg-purple-dark","name":"Charcoal","color":"#1f1f1f"},{"slug":"focus-yellow","name":"Gold","color":"#d4af37"},{"slug":"dark-gold","name":"Dark gold","color":"#7a5c00"},{"slug":"text-black","name":"Text Black","color":"#0b0c0c"},{"slug":"footer-grey","name":"Footer black","color":"#0b0c0c"},{"slug":"light-grey","name":"Light Grey","color":"#f3f2f1"},{"slug":"light-purple","name":"Cream","color":"#faf6e9"},{"slug":"white","name":"White","color":"#ffffff"}]}},"typography":{"fontFamilies":{"custom":[{"name":"Kantumruy Pro","slug":"kantumruy-pro","fontFamily":"\\"Kantumruy Pro\\", sans-serif","fontFace":[{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"400","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-400.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"600","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-600.woff2"},{"fontFamily":"\\"Kantumruy Pro\\"","fontStyle":"normal","fontWeight":"700","src":"https://rbg-coursework-demo.page.gd/wp-content/uploads/fonts/kantumruy-pro-700.woff2"}]},{"name":"System Sans","slug":"system-sans","fontFamily":"-apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Arial, sans-serif"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}','Custom Styles','','inherit','closed','closed','','5-revision-v1','','','2026-11-22 16:33:09','2026-11-22 16:33:09','',5,'https://rbg-coursework-demo.page.gd/?p=113',0,'revision','',0);
