INSERT INTO `wp_posts` VALUES (116,4,'2026-11-22 17:40:19','0000-00-00 00:00:00','<!-- wp:paragraph -->\n<p>Greenwich spans both the Royal Borough of Greenwich in London and Greenwich, Connecticut, with<strong> <mark>major local updates around council policies, housing, and community events</mark>.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','NEWS OF GREENWICH','','pending','closed','closed','','','','','2026-11-22 17:40:19','2026-11-22 17:40:19','',0,'https://rbg-coursework-demo.page.gd/?p=116',0,'post','',0);
