-- RBG coursework demo: database for https://rbg-coursework-demo.page.gd
-- Keeps the password set during the WordPress install for user ID 1 (akindu).
DROP TABLE IF EXISTS `rbg_keep`;
CREATE TABLE `rbg_keep` AS SELECT `user_pass` FROM `wp_users` WHERE `ID` = 1;

